(function(){"use strict";var M=window.MNEMIKA;if(!M||M.__r154q)return;M.__r154q=true;
/* R154 (eigenes Modul, Muster R153): Fragen zu den neuen, lehrplanbasierten Lernzielen, die noch keine eigene Pruefung hatten. Nichts wird entfernt; IDs <kapitel>-r154-n. Antwortpositionen deterministisch gemischt. */
var Z={"v76-gym-german-02-argumentieren-und-schreiben":[{"type":"mc","prompt":"Ein Entwurf besteht aus Absätzen, die einzeln stimmen, aber ohne Überleitungen und ohne erkennbaren Leitgedanken aneinandergereiht sind. Welches Überarbeitungskriterium ist vor allem verletzt?","options":["Kohärenz","Präzision","Satzvarianz","Rechtschreibung"],"answer":0,"explanation":"Kohärenz verlangt einen Leitgedanken pro Absatz und Übergänge, die den logischen Zusammenhang zeigen; genau das fehlt hier, während Präzision, Rechtschreibung und Satzvarianz andere Ebenen betreffen.","difficulty":2}],"v76-gym-french-01-rezeption":[{"type":"mc","prompt":"Im Text steht: «Elle a acheté trois romans à la librairie du quartier.» Was bedeutet «librairie» in diesem Satz?","options":["Schreibwarenladen","Buchhandlung","Bibliothek","Verlag"],"answer":1,"explanation":"«La librairie» ist ein faux ami: Es bedeutet Buchhandlung, die Bibliothek heisst «la bibliothèque»; zudem passt «acheter» nur zu einem Geschäft.","difficulty":1}],"v76-gym-french-02-mundliche-interaktion":[{"type":"mc","prompt":"Du willst im Gespräch höflich Zweifel an einem Vorschlag äussern. Welcher Satz ist grammatisch korrekt?","options":["Je pense que ce soit une bonne idée.","Je ne pense pas que ce sera une bonne idée.","Je ne pense pas que ce soit une bonne idée.","Je ne pense pas que c'est une bonne idée."],"answer":2,"explanation":"Wird «je pense que» verneint, drückt der Satz Zweifel aus, darum folgt der subjonctif «soit»; nach bejahtem «je pense que» stünde dagegen der indicatif.","difficulty":2}],"v76-gym-french-03-schriftliche-produktion":[{"type":"mc","prompt":"Mit welcher Schlussformel endet ein formeller Brief an eine unbekannte Person korrekt?","options":["Veuillez agréer, Madame, Monsieur, l'expression de mes salutations distinguées.","Je t'embrasse fort, à bientôt.","Salut et bonne journée !","Bien à toi, et merci encore."],"answer":0,"explanation":"Der formelle Brief verlangt die feste Formel mit «Veuillez agréer», in der die Anrede wiederholt wird; die anderen Wendungen duzen oder sind umgangssprachlich.","difficulty":1}],"v76-gym-french-04-kultur-und-literatur":[{"type":"mc","prompt":"Wo lebt heute mehr als die Hälfte aller Menschen, die Französisch sprechen?","options":["In Kanada","In Afrika","In Frankreich","In Belgien und der Schweiz zusammen"],"answer":1,"explanation":"Die Frankophonie reicht weit über Europa hinaus; durch Länder wie Senegal, Elfenbeinküste und Kongo lebt heute mehr als die Hälfte der Französischsprechenden in Afrika.","difficulty":2}],"v76-gym-languages-01-rezeption":[{"type":"mc","prompt":"Text: «The museum opened in 1998 and attracts many tourists every summer.» Aussage: «The museum is the most popular attraction in the city.» Welche Antwort ist richtig?","options":["False","False, weil das Jahr 1998 nicht stimmt","Not given","True"],"answer":2,"explanation":"Der Text sagt nichts darüber, ob das Museum die beliebteste Attraktion ist; er widerspricht der Aussage auch nicht, darum ist sie Not given und eigenes Vorwissen zählt nicht.","difficulty":2},{"type":"mc","prompt":"«Once again, the so-called reform has changed nothing for ordinary families.» Welche Haltung zeigt der Autor gegenüber der Reform?","options":["Skeptisch bis ablehnend","Unentschieden fragend","Begeistert zustimmend","Neutral informierend"],"answer":0,"explanation":"Wertende Wendungen wie «so-called», «once again» und «changed nothing» verraten Skepsis; ein neutraler Text würde die Reform ohne solche Wertungen beschreiben.","difficulty":2}],"v76-gym-languages-02-produktion":[{"type":"mc","prompt":"Welcher Satz ist korrekt?","options":["I am living in Zurich since three years.","I live in Zurich since three years.","I have lived in Zurich for three years.","I have lived in Zurich since three years."],"answer":2,"explanation":"Für eine Dauer bis heute steht das present perfect mit «for» vor einer Zeitspanne; «since» braucht einen Zeitpunkt, und das simple present passt nicht zu einer andauernden Dauer.","difficulty":2},{"type":"mc","prompt":"Welche Formulierung passt in eine formelle Anfrage an eine Firma?","options":["I wanna get some more info from you.","Hey, can you send me the info?","Send me more info, please!","I would be grateful if you could send me further information."],"answer":3,"explanation":"Formelles Register verlangt höfliche, indirekte Wendungen ohne Kurzformen und Umgangssprache; nur die erste Option erfüllt das.","difficulty":1}],"v76-gym-languages-03-interaktion":[{"type":"mc","prompt":"Your partner says: «Homework should be abolished.» Welche Reaktion widerspricht höflich und hält das Gespräch am Laufen?","options":["I see what you mean, but have you considered that homework helps us practise?","No, that's not true.","You're wrong, homework is important.","Whatever, let's talk about something else."],"answer":0,"explanation":"Die erste Antwort anerkennt den Punkt, bringt ein Gegenargument und gibt mit einer Rückfrage den Ball zurück; die anderen wirken schroff oder brechen das Gespräch ab.","difficulty":1}],"v76-gym-languages-04-literatur-und-kulturelle-kontexte":[{"type":"mc","prompt":"«Time is a thief.» Welches sprachliche Mittel liegt in diesem Vers vor?","options":["simile","metaphor","onomatopoeia","alliteration"],"answer":1,"explanation":"Die Zeit wird ohne Vergleichswort wie «like» oder «as» mit einem Dieb gleichgesetzt, das ist eine metaphor; ein simile bräuchte ein Vergleichswort.","difficulty":1},{"type":"mc","prompt":"Welches Werk ist eine Tragödie von William Shakespeare?","options":["A Midsummer Night's Dream","Macbeth","Pride and Prejudice","Great Expectations"],"answer":1,"explanation":"Macbeth gehört mit Hamlet zu Shakespeares Tragödien; A Midsummer Night's Dream ist eine Komödie, die beiden anderen sind Romane von Austen und Dickens.","difficulty":1}],"v76-gym-math-02-analysis":[{"type":"numeric","prompt":"Bestimme die Tangente an f(x) = x² im Punkt mit x₀ = 2 in der Form y = m · x + q. Wie gross ist q (ohne Einheit)?","answer":-4,"tolerance":0.001,"explanation":"Es gilt f(2) = 4 und f′(x) = 2x, also m = 4; aus 4 = 4 · 2 + q folgt q = −4, die Tangente lautet y = 4x − 4.","difficulty":2},{"type":"numeric","prompt":"Ein Rechteck hat den Umfang 24 cm. Wie gross ist die grösstmögliche Fläche (in cm²)?","answer":36,"tolerance":0.01,"explanation":"Aus 2x + 2y = 24 folgt y = 12 − x, also A(x) = 12x − x²; A′(x) = 12 − 2x = 0 ergibt x = 6, A″ = −2 < 0 bestätigt das Maximum A = 36 cm².","difficulty":2}],"v76-gym-math-03-geometrie-und-vektoren":[{"type":"mc","prompt":"Gegeben sind g: X = (0, 0, 0) + t · (1, 1, 0) und h: X = (4, 0, 0) + s · (−1, 1, 0). Wie liegen die beiden Geraden zueinander?","options":["Sie sind identisch.","Sie sind parallel, aber nicht identisch.","Sie schneiden sich im Punkt S(2 | 2 | 0).","Sie sind windschief."],"answer":2,"explanation":"Die Richtungen sind keine Vielfachen voneinander; aus t = 4 − s und t = s folgt t = s = 2, die dritte Koordinate 0 = 0 stimmt, also schneiden sie sich in S(2 | 2 | 0).","difficulty":3}],"v76-gym-math-04-stochastik-und-modellierung":[{"type":"numeric","prompt":"Bestimme den Median der Messwerte 3, 9, 4, 12 und 7 (ohne Einheit).","answer":7,"tolerance":0.001,"explanation":"Sortiert lauten die Werte 3, 4, 7, 9, 12; bei fünf Werten ist der dritte der mittlere, also ist der Median 7.","difficulty":1}],"v76-gym-informatics-01-daten-und-reprasentation":[{"type":"numeric","prompt":"Das grosse A hat im ASCII-Code den Wert 65. Welchen ASCII-Code hat das grosse C (Dezimalzahl)?","answer":67,"tolerance":0,"explanation":"Die Grossbuchstaben liegen in ASCII lückenlos in alphabetischer Reihenfolge: A = 65, B = 66, also C = 67.","difficulty":1}],"v76-gym-informatics-03-systeme-und-netze":[{"type":"mc","prompt":"Anna will Bob mit asymmetrischer Verschlüsselung eine vertrauliche Nachricht schicken. Mit welchem Schlüssel muss sie die Nachricht verschlüsseln?","options":["Mit Bobs öffentlichem Schlüssel","Mit Bobs privatem Schlüssel","Mit ihrem eigenen öffentlichen Schlüssel","Mit einem gemeinsamen geheimen Schlüssel"],"answer":0,"explanation":"Was mit Bobs öffentlichem Schlüssel verschlüsselt wird, kann nur Bobs privater Schlüssel entschlüsseln, den nur Bob besitzt. Ein gemeinsamer geheimer Schlüssel gehört zur symmetrischen Verschlüsselung.","difficulty":2}],"v76-gym-informatics-04-digitale-verantwortung":[{"type":"mc","prompt":"Eine Fitness-App verlangt zum Schrittezählen rund um die Uhr Zugriff auf Kontakte, Fotos und den genauen Standort. Gegen welchen Grundsatz des Datenschutzgesetzes verstösst das am deutlichsten?","options":["Verfügbarkeit","Verhältnismässigkeit (Datenminimierung)","Urheberrecht","Integrität"],"answer":1,"explanation":"Für das Zählen von Schritten sind Kontakte und Fotos nicht nötig; bearbeitet werden dürfen nur so viele Personendaten, wie der Zweck erfordert. Verfügbarkeit und Integrität sind Schutzziele der Informationssicherheit.","difficulty":2},{"type":"mc","prompt":"Ein Bewerbungsprogramm wurde mit den Einstellungen der letzten zwanzig Jahre trainiert, in denen fast nur Männer eingestellt wurden. Welche Folge ist am wahrscheinlichsten?","options":["Es hat keine Folgen, weil Trainingsdaten das Ergebnis nicht beeinflussen","Es bevorzugt Bewerberinnen, um den früheren Rückstand auszugleichen","Es benachteiligt Bewerberinnen, weil es die Verzerrung der Trainingsdaten übernimmt","Es ist besonders fair, weil ein Computer keine Meinung hat"],"answer":2,"explanation":"KI-Systeme lernen Muster aus ihren Trainingsdaten; enthalten diese Vorurteile, übernimmt das System sie (algorithmische Verzerrung). Darum braucht es Transparenz und menschliche Kontrolle.","difficulty":2}],"v76-gym-biology-03-okologie-und-evolution":[{"type":"numeric","prompt":"Bakterien teilen sich unter idealen Bedingungen alle 30 Minuten. Um welchen Faktor ist die Population nach 4 Stunden unbegrenzten Wachstums grösser? (Faktor)","answer":256,"tolerance":0,"explanation":"In 4 Stunden finden 8 Verdoppelungen statt; exponentielles Wachstum ergibt deshalb 2⁸ = 256.","difficulty":2}],"v76-gym-chemistry-01-stoffe-und-teilchen":[{"type":"mc","prompt":"Ordne die Stoffe CH₄, H₂S und H₂O nach steigendem Siedepunkt.","options":["H₂S < CH₄ < H₂O","CH₄ < H₂S < H₂O","H₂O < H₂S < CH₄","CH₄ < H₂O < H₂S"],"answer":1,"explanation":"CH₄ ist unpolar und hat nur Van-der-Waals-Kräfte, H₂S ist polar mit Dipol-Dipol-Kräften, H₂O bildet Wasserstoffbrücken und siedet deshalb am höchsten.","difficulty":2},{"type":"mc","prompt":"Natrium hat die Elektronegativität 0,9, Chlor 3,0. Welche Bindung liegt in Natriumchlorid vor?","options":["Metallbindung","Polare Atombindung","Unpolare Atombindung","Ionenbindung"],"answer":3,"explanation":"Die Differenz beträgt 3,0 − 0,9 = 2,1 und liegt damit über etwa 1,7; Natrium gibt sein Valenzelektron an Chlor ab, es entstehen Na⁺- und Cl⁻-Ionen.","difficulty":1}],"v76-gym-chemistry-02-reaktionen-und-energie":[{"type":"numeric","prompt":"Methan verbrennt mit ΔH ≈ −890 kJ/mol. Wie viel Wärme wird frei, wenn 48 g Methan (M = 16 g/mol) vollständig verbrennen? (kJ)","answer":2670,"tolerance":5,"explanation":"48 g / 16 g/mol = 3 mol; die Wärme ist proportional zur Stoffmenge, also werden 3 · 890 kJ = 2670 kJ frei.","difficulty":2}],"v76-gym-chemistry-03-gleichgewichte-und-saure-base":[{"type":"mc","prompt":"Wie lautet das Massenwirkungsgesetz für die Ammoniaksynthese N₂ + 3 H₂ ⇌ 2 NH₃?","options":["K = [N₂] · [H₂]³ / [NH₃]²","K = [NH₃]² / ([N₂] · [H₂]³)","K = 2 · [NH₃] / ([N₂] + 3 · [H₂])","K = [NH₃] / ([N₂] · [H₂])"],"answer":1,"explanation":"Im Zähler stehen die Produkte, im Nenner die Edukte, jeweils hoch ihrem Koeffizienten aus der Reaktionsgleichung; Koeffizienten werden nicht als Faktoren addiert.","difficulty":2}],"v76-gym-physics-01-mechanik":[{"type":"mc","prompt":"Jemand berechnet für einen Stein, der aus der Ruhe 2,0 s frei fällt, eine Fallstrecke von 196 m. Welche Kontrolle zeigt am schnellsten, dass das nicht stimmen kann?","options":["Nach 2 s ist der Stein etwa 20 m/s schnell, im Mittel also etwa 10 m/s; in 2 s fällt er darum nur rund 20 m.","Das Resultat ist plausibel, weil ein schwerer Stein schneller fällt als ein leichter.","Die Einheit Meter stimmt, darum muss auch das Resultat stimmen.","Mit g = 10 m/s² statt 9,81 m/s² nachrechnen, weil die Rundung den grossen Unterschied erklärt."],"answer":0,"explanation":"Die mittlere Geschwindigkeit liefert einen zweiten Weg: 10 m/s · 2 s = 20 m, genau gerechnet s = ½ · 9,81 m/s² · (2,0 s)² ≈ 19,6 m; 196 m ist zehnmal zu gross, obwohl die Einheit stimmt.","difficulty":2}],"v76-gym-physics-04-wellen-und-moderne-physik":[{"type":"mc","prompt":"Ein Lichtstrahl tritt schräg aus Luft in Wasser (n = 1,33) über. Wie ändert sich seine Richtung?","options":["Er wird an der Wasseroberfläche vollständig reflektiert","Er wird zum Lot hin gebrochen, weil Licht im Wasser langsamer ist","Er wird vom Lot weg gebrochen, weil Licht im Wasser schneller ist","Er läuft ohne Richtungsänderung weiter"],"answer":1,"explanation":"Im optisch dichteren Wasser sinkt die Lichtgeschwindigkeit, darum wird der Strahl zum Lot hin gebrochen. Totalreflexion gibt es nur beim Übergang ins optisch dünnere Medium.","difficulty":2}],"v76-gym-geography-01-geosysteme":[{"type":"mc","prompt":"Granit wird über Jahrmillionen verwittert, abgetragen, abgelagert und verfestigt. Welche Gesteinsgruppe entsteht dabei?","options":["Magmatit (Tiefengestein)","Ergussgestein","Sedimentgestein","Metamorphit"],"answer":2,"explanation":"Verwitterung, Abtragung, Ablagerung und Verfestigung sind exogene Vorgänge, die aus Bruchstücken Sedimentgestein bilden; Metamorphite entstehen dagegen durch Druck und Hitze in der Tiefe.","difficulty":2}],"v76-gym-geography-04-nachhaltigkeit-und-raumplanung":[{"type":"mc","prompt":"Was verlangt die Definition nachhaltiger Entwicklung, welche die Brundtland-Kommission der UNO 1987 formulierte?","options":["Nur noch erneuerbare Energie nutzen, unabhängig von Kosten und sozialen Folgen","Das Wirtschaftswachstum jedes Jahr maximieren, damit künftige Generationen reicher sind","Die Natur vollständig vor jeder menschlichen Nutzung schützen","Die Bedürfnisse der Gegenwart befriedigen, ohne die Möglichkeiten künftiger Generationen zu gefährden"],"answer":3,"explanation":"Brundtland verbindet Gegenwart und Zukunft (Generationengerechtigkeit); reines Wachstum, reine Ökologie oder totaler Schutz lassen jeweils Dimensionen weg.","difficulty":1},{"type":"mc","prompt":"Eine Gemeinde will eine Wohnüberbauung auf einer Obstwiese am Dorfrand bewilligen. Welches Vorgehen beurteilt diesen Nutzungskonflikt fachlich am besten?","options":["Nur die Kosten für die Gemeinde berechnen, weil sie die Erschliessung bezahlt","Akteure und Interessen nennen, das Projekt ökologisch, wirtschaftlich und gesellschaftlich prüfen, Alternativen wie Verdichtung abwägen, dann begründet entscheiden","Ablehnen, weil jede Bebauung einer Grünfläche grundsätzlich nicht nachhaltig ist","Zustimmen, weil neuer Wohnraum immer Vorrang vor der Natur hat"],"answer":1,"explanation":"Ein tragfähiges Urteil berücksichtigt alle Akteure und alle drei Dimensionen und wägt Alternativen ab; die anderen Antworten urteilen pauschal oder nur nach einem Kriterium.","difficulty":2},{"type":"tf","prompt":"Ein gutes Urteil über einen Nutzungskonflikt nennt die Interessen aller Akteure fair, auch wenn es am Ende einer Seite recht gibt.","options":["Richtig","Falsch"],"answer":0,"explanation":"Richtig: Erst die faire Darstellung aller Interessen macht die Abwägung nachvollziehbar; das Urteil darf trotzdem eindeutig ausfallen.","difficulty":1}],"v76-gym-economics-02-betriebswirtschaft":[{"type":"mc","prompt":"Ein Velohersteller verkauft ein neues E-Bike nur noch über den eigenen Onlineshop statt über Fachgeschäfte. Welches Instrument des Marketing-Mix verändert er?","options":["Distribution","Produkt","Kommunikation","Preis"],"answer":0,"explanation":"Die Distribution bestimmt, wie das Produkt zum Kunden gelangt; der Wechsel vom indirekten Weg über den Handel zum Direktvertrieb ist eine Distributionsentscheidung.","difficulty":1},{"type":"numeric","prompt":"Eine Maschine kostet 90 000 Franken und spart jährlich 18 000 Franken ein. Wie lange dauert die Amortisation nach der Payback-Methode? (Jahre)","answer":5,"tolerance":0,"explanation":"Payback = Investition / jährlicher Rückfluss = 90 000 / 18 000 = 5 Jahre; danach ist das eingesetzte Kapital zurückgeflossen.","difficulty":1}],"v76-gym-economics-03-recht-und-staat":[{"type":"mc","prompt":"Eine Joggerin stösst aus Unachtsamkeit einen Passanten um, der sich das Handgelenk bricht. Welche Voraussetzungen müssen für eine Haftung nach Art. 41 OR alle erfüllt sein?","options":["Schaden und Kausalzusammenhang, wobei Unachtsamkeit nie als Verschulden gilt","Schaden, Widerrechtlichkeit, adäquater Kausalzusammenhang und Verschulden","Nur Verschulden, ein Schaden muss nicht nachgewiesen werden","Schaden, ein Vertrag zwischen den Beteiligten, Vorsatz und eine Strafanzeige"],"answer":1,"explanation":"Art. 41 OR verlangt alle vier Voraussetzungen; Fahrlässigkeit wie Unachtsamkeit ist Verschulden, ein Vertrag ist für die ausservertragliche Haftung nicht nötig.","difficulty":2}],"v76-gym-social-01-argumentanalyse":[{"type":"mc","prompt":"Bestimme die Konklusion im Argument: Rauchen schadet der Gesundheit; was der Gesundheit schadet, sollte man meiden; also sollte man das Rauchen meiden.","options":["Rauchen schadet der Gesundheit","Was der Gesundheit schadet, sollte man meiden","Das Argument hat keine Konklusion, nur Prämissen","Also sollte man das Rauchen meiden"],"answer":3,"explanation":"Die Konklusion ist die Aussage, die begründet werden soll; das Signalwort also leitet sie ein, die beiden anderen Sätze sind Prämissen.","difficulty":1}],"v76-gym-projects-01-fragestellung":[{"type":"tf","prompt":"Eine Hypothese muss so formuliert sein, dass die erhobenen Daten sie stützen oder widerlegen können; auch eine widerlegte Hypothese ist ein gültiges Ergebnis.","options":["Richtig","Falsch"],"answer":0,"explanation":"Richtig: Eine Hypothese ist eine prüfbare Vermutung; zeigt die Messung keinen Unterschied, wird dieses Ergebnis sauber dargestellt und gedeutet.","difficulty":1}],"v76-gym-projects-03-auswertung":[{"type":"mc","prompt":"Eine Umfrage in einer Klasse (n = 40) zeigt: Wer mehr Zeit am Handy verbringt, hat im Durchschnitt tiefere Noten. Welche Deutung ist folgerichtig?","options":["Die Ergebnisse gelten für alle Jugendlichen der Schweiz.","Die Daten zeigen, dass gute Schüler keine Handys besitzen.","In dieser Stichprobe hängen Handyzeit und Noten zusammen; eine Ursache ist damit nicht belegt.","Handys verursachen schlechte Noten."],"answer":2,"explanation":"Ein Zusammenhang (Korrelation) beweist keine Ursache, und eine einzelne Klasse ist nicht repräsentativ; die vorsichtige Deutung nennt beides.","difficulty":2}],"v76-gym-projects-04-prasentation-und-verteidigung":[{"type":"mc","prompt":"Du gestaltest die Ergebnisfolie deiner Maturaarbeit über Musik beim Lernen. Welcher Folientitel unterstützt den Vortrag am besten?","options":["Kapitel 4.2 der Arbeit","Gesangsmusik senkt die Lernleistung um ein Viertel","Meine Daten in einer Tabelle mit allen 60 Messwerten","Ergebnisse"],"answer":1,"explanation":"Ein Titel, der die Aussage nennt, zeigt dem Publikum sofort die Kernbotschaft; neutrale Titel oder volle Tabellen tun das nicht.","difficulty":1}],"v76-gym-orientation-02-politische-bildung":[{"type":"mc","prompt":"Ein Wirtschaftsverband bekämpft eine Vorlage, eine Umweltorganisation unterstützt sie. Welcher Schritt hilft dir am meisten, ein eigenes Urteil zu bilden?","options":["Klären, was sich ändern würde, die Interessen hinter den Argumenten benennen und die Argumente nach Kriterien abwägen.","Der Parole der grössten Partei folgen.","Nur das Argument lesen, das am meisten Aufmerksamkeit erhält.","Abwarten, wie die Mehrheit in Umfragen abstimmt."],"answer":0,"explanation":"Ein begründetes Urteil entsteht, wenn man Inhalt, Interessen und Argumente selbst prüft und gewichtet, statt fremden Parolen oder Mehrheiten zu folgen.","difficulty":2}],"v76-gym-orientation-03-bildung-fur-nachhaltige-entwicklung":[{"type":"mc","prompt":"Eis schmilzt, die dunklere Fläche nimmt mehr Wärme auf, dadurch schmilzt noch mehr Eis. Um welche Art von Rückkopplung handelt es sich?","options":["Rebound-Effekt","Verstärkende (positive) Rückkopplung","Ausgleichende (negative) Rückkopplung","Keine Rückkopplung, nur eine einfache Ursache-Wirkungs-Kette"],"answer":1,"explanation":"Die Wirkung (weniger Eis) verstärkt ihre eigene Ursache (Erwärmung), das System schaukelt sich auf; das ist eine verstärkende Rückkopplung.","difficulty":2},{"type":"mc","prompt":"Warum führt das Verbrennen von Kohle, Erdöl und Gas zu einer Erwärmung der Erde?","options":["Die bei der Verbrennung frei werdende Abwärme heizt die Atmosphäre direkt auf","Es zerstört die Ozonschicht, sodass mehr Sonnenwärme auf die Erde gelangt","Es erhöht die CO₂-Konzentration, und CO₂ hält einen Teil der Wärmestrahlung der Erde zurück","CO₂ hält das einfallende Sonnenlicht in der oberen Atmosphäre fest"],"answer":2,"explanation":"CO₂ lässt Sonnenlicht durch, hält aber einen Teil der Wärmestrahlung der Erde zurück; mehr CO₂ verstärkt den natürlichen Treibhauseffekt. Ozonabbau und direkte Abwärme sind nicht die Ursache.","difficulty":1},{"type":"mc","prompt":"Was beschreibt das Modell der planetaren Belastungsgrenzen der Forschungsgruppe um Johan Rockström?","options":["Die grösste Zahl von Menschen, welche die Erde dauerhaft ernähren kann","Neun Prozesse des Erdsystems mit je einer Grenze, innerhalb der die Menschheit sicher handeln kann","Die Grenzwerte für Luftschadstoffe, die in der Schweiz gesetzlich gelten","Die drei Dimensionen der Nachhaltigkeit, die gleich stark gewichtet werden müssen"],"answer":1,"explanation":"Das Modell nennt neun Erdsystemprozesse wie Klimawandel, Artenvielfalt oder Stickstoffkreislauf mit je einer sicheren Grenze; es ist weder eine Bevölkerungsgrenze noch ein Gesetz.","difficulty":1}],"v76-smp-german-02-sprachrichtigkeit":[{"type":"mc","prompt":"Welcher Satz ist in der Schreibung von das und dass vollständig richtig?","options":["Ich weiss, das er kommt.","Ich hoffe, das das Buch gefällt.","Das Buch, dass auf dem Tisch liegt, gehört mir.","Es ist wichtig, dass wir das verstehen."],"answer":3,"explanation":"Dass leitet als Konjunktion einen Nebensatz ein; das lässt sich durch dieses oder welches ersetzen. Nur im dritten Satz stimmen beide Formen.","difficulty":2}],"v76-smp-german-03-literaturanalyse":[{"type":"mc","prompt":"Im Fünf-Akt-Schema nach Freytag kommt es am Höhepunkt oft zu einem Umschwung der Handlung. Wie heisst dieser Umschwung?","options":["Exposition","Erregendes Moment","Retardierendes Moment","Peripetie"],"answer":3,"explanation":"Die Peripetie ist der Umschwung am Höhepunkt; die Exposition führt ein, das erregende Moment löst den Konflikt aus, das retardierende Moment verzögert die Katastrophe.","difficulty":2}],"v76-smp-french-03-schriftlicher-ausdruck":[{"type":"mc","prompt":"Bei der Kontrolle deines Briefs findest du: «Bien que le cours est cher, je veux le suivre.» Welche Korrektur ist richtig?","options":["Bien que le cours être cher, je veux le suivre.","Bien que le cours sera cher, je veux le suivre.","Bien que le cours était cher, je veux le suivre.","Bien que le cours soit cher, je veux le suivre."],"answer":3,"explanation":"Nach bien que steht immer der subjonctif; die subjonctif-Form von être in der dritten Person ist soit.","difficulty":2}],"v76-smp-french-04-literatur":[{"type":"mc","prompt":"Voltaires «Candide» (1759) kritisiert Vorurteile und blinden Optimismus im Namen der Vernunft. Welcher Epoche ordnest du das Werk zu?","options":["Realismus (le réalisme)","Romantik (le romantisme)","Klassizismus (le classicisme)","Aufklärung (les Lumières)"],"answer":3,"explanation":"Candide erschien 1759 und kritisiert im Namen der Vernunft Kirche und Vorurteile; das sind Kennzeichen der Aufklärung im 18. Jahrhundert.","difficulty":1}],"v76-smp-french-05-mundliche-prufung":[{"type":"mc","prompt":"Ein Kandidat sagt in der Prüfung: «Je pense pas que c'est vrai.» Welche Fassung ist korrekt?","options":["Je pense pas que ce soit vrai.","Je ne pense pas que ce soit vrai.","Je ne pense pas que c'est vraie.","Je ne pense que c'est vrai."],"answer":1,"explanation":"Die Verneinung braucht ne … pas, und nach je ne pense pas que steht meist der subjonctif; daher ce soit vrai.","difficulty":2}],"v76-smp-english-04-freier-ausdruck":[{"type":"mc","prompt":"Welche Formulierung macht aus der Behauptung «Public transport should be free» ein vollständiges Argument?","options":["Public transport should be free, and I really think so.","Public transport should be free, because it would reduce traffic and emissions in city centres.","Public transport should definitely and absolutely be free.","Many people say that public transport should be free."],"answer":1,"explanation":"Ein Argument verbindet eine Behauptung mit einer Begründung; nur die erste Variante liefert mit because einen Grund, die anderen wiederholen oder verstärken bloss die Meinung.","difficulty":2}],"v76-smp-english-05-literatur-und-mundliche-prufung":[{"type":"mc","prompt":"Eine Kandidatin wählt für die Normalstufe: Orwell, Animal Farm; Orwell, Nineteen Eighty-Four; Golding, Lord of the Flies. Welche Aussage beschreibt einen Mangel dieser Auswahl richtig?","options":["Es sind nur zwei verschiedene Autoren; verlangt sind drei Werke von drei verschiedenen Autoren.","Romane sind als Gattung nicht zugelassen.","Die Werke sind zu kurz, weil mindestens 1000 Seiten verlangt sind.","Es fehlt ein Werk; verlangt sind mindestens fünf Werke."],"answer":0,"explanation":"Die Richtlinien verlangen mindestens drei Werke von drei verschiedenen Autoren aus zwei Epochen und Gattungen; Orwell erscheint doppelt, und alle drei Werke sind Romane.","difficulty":2},{"type":"mc","prompt":"Was klärst du beim ersten Lesen des Auszugs in der Vorbereitungszeit zuerst?","options":["Welche unbekannten Wörter du im Wörterbuch nachschlagen musst.","Wie du den ganzen Auszug wörtlich auswendig lernst.","Wo die Stelle im Werk liegt: wer spricht, wann im Verlauf und in welcher Situation.","Welche Biografie des Autors du vollständig vortragen willst."],"answer":2,"explanation":"Die Einordnung des Auszugs ins ganze Werk ist der Ausgangspunkt der Deutung; ohne sie bleibt die Analyse der Gestaltungsmerkmale ohne Zusammenhang.","difficulty":1}],"v76-smp-math-01-algebra-und-funktionen":[{"type":"mc","prompt":"Welche Aussage über die Funktion f(x) = ln(x) ist korrekt?","options":["Sie ist periodisch mit der Periode 2π.","Sie ist für alle reellen x definiert und hat bei x = 0 ihre Nullstelle.","Sie ist nur für x > 0 definiert und hat bei x = 1 ihre Nullstelle.","Ihr Graph ist achsensymmetrisch zur y-Achse."],"answer":2,"explanation":"Der Logarithmus ist die Umkehrfunktion von e hoch x, deren Werte immer positiv sind; darum ist ln nur für x > 0 definiert, und wegen e hoch 0 = 1 gilt ln(1) = 0.","difficulty":2}],"v76-smp-math-02-analysis":[{"type":"numeric","prompt":"Die Tangente an den Graphen von f(x) = x² im Punkt mit x = 1 hat die Gleichung y = mx + q. Wie gross ist q?","answer":-1,"tolerance":0,"explanation":"Es gilt f(1) = 1 und f'(x) = 2x, also m = f'(1) = 2. Einsetzen von P(1 | 1) in y = 2x + q ergibt 1 = 2 + q, also q = −1.","difficulty":2}],"v76-smp-math-03-vektorgeometrie":[{"type":"numeric","prompt":"Wie gross ist der Winkel zwischen den Vektoren a = (1, 0, 0) und b = (1, 1, 0) in Grad?","answer":45,"tolerance":0.5,"explanation":"a · b = 1, |a| = 1 und |b| = √2, also cos φ = 1 / √2 ≈ 0,707 und damit φ = 45°.","difficulty":2},{"type":"mc","prompt":"Die Richtungsvektoren zweier Geraden im Raum sind nicht kollinear, und das Gleichsetzen der Geradengleichungen ergibt ein unlösbares Gleichungssystem. Wie liegen die Geraden zueinander?","options":["Sie sind identisch.","Sie sind parallel.","Sie sind windschief.","Sie schneiden sich in genau einem Punkt."],"answer":2,"explanation":"Nicht kollineare Richtungsvektoren schliessen parallel und identisch aus; weil kein gemeinsamer Punkt existiert, schneiden sie sich auch nicht, also sind sie windschief.","difficulty":2}],"v76-smp-biology-01-zellbiologie-und-genetik":[{"type":"mc","prompt":"Worin unterscheidet sich das Ergebnis der Meiose von dem der Mitose beim Menschen?","options":["Die Meiose liefert zwei diploide, identische Zellen, die Mitose vier haploide Zellen.","Beide liefern vier haploide Zellen, nur die Dauer ist verschieden.","Die Meiose liefert vier haploide, genetisch verschiedene Zellen, die Mitose zwei diploide, genetisch identische Zellen.","Die Meiose verdoppelt den Chromosomensatz auf 92 Chromosomen."],"answer":2,"explanation":"In der Meiose werden zuerst die homologen Chromosomen, dann die Chromatiden getrennt; so entstehen vier haploide Keimzellen mit neuer Kombination, während die Mitose identische Körperzellen erzeugt.","difficulty":2},{"type":"mc","prompt":"Der codogene DNA-Strang lautet TAC. Welches mRNA-Codon entsteht bei der Transkription?","options":["AUG","UAC","ATG","TAC"],"answer":0,"explanation":"Die mRNA ist komplementär zum codogenen Strang: T wird zu A, A zu U, C zu G; RNA enthält Uracil statt Thymin, darum ist ATG falsch.","difficulty":2}],"v76-smp-biology-02-humanbiologie":[{"type":"mc","prompt":"Was geschieht bei der Depolarisation während eines Aktionspotenzials an der Membran einer Nervenzelle?","options":["Kaliumionen strömen ein, und das Zellinnere wird stärker negativ.","Spannungsabhängige Natriumkanäle öffnen sich, Natriumionen strömen ein, und das Zellinnere wird kurz positiv.","Neurotransmitter werden direkt ins Axoninnere aufgenommen.","Die Natrium-Kalium-Pumpe stoppt, und die Zelle bleibt bei −70 Millivolt."],"answer":1,"explanation":"Wird der Schwellenwert überschritten, öffnen sich Natriumkanäle; der Natriumeinstrom kehrt die Ladung um, erst danach stellt der Kaliumausstrom das Ruhepotenzial wieder her.","difficulty":2}],"v76-smp-chemistry-01-atome-und-bindungen":[{"type":"mc","prompt":"Welche Molekülgeometrie sagt das Elektronenpaarabstossungsmodell für das Wassermolekül H₂O voraus?","options":["Tetraedrisch mit vier Wasserstoffatomen.","Gewinkelt, weil zwei bindende und zwei freie Elektronenpaare tetraedrisch angeordnet sind.","Trigonal planar mit Winkeln von 120°.","Linear, weil nur zwei Wasserstoffatome gebunden sind."],"answer":1,"explanation":"Am Sauerstoff liegen vier Elektronenpaare, davon zwei freie; sie stossen sich tetraedrisch ab, sichtbar bleiben nur die zwei Bindungen, darum ist das Molekül gewinkelt (etwa 105°).","difficulty":2},{"type":"mc","prompt":"Ethanol siedet bei 78 °C, Propan mit ähnlicher Molekülmasse bei −42 °C. Was erklärt den Unterschied?","options":["Ethanol ist eine Ionenverbindung mit Ionengitter.","Ethanolmoleküle bilden über ihre OH-Gruppe Wasserstoffbrücken, Propanmoleküle nur schwache Van-der-Waals-Kräfte.","Beim Sieden von Ethanol müssen die O–H-Bindungen im Molekül gespalten werden.","Propan hat stärkere Dipol-Dipol-Kräfte als Ethanol."],"answer":1,"explanation":"Beim Sieden werden nur Kräfte zwischen Molekülen überwunden; die Wasserstoffbrücken zwischen Ethanolmolekülen sind viel stärker als die Van-der-Waals-Kräfte des unpolaren Propans.","difficulty":2}],"v76-smp-chemistry-03-energetik-und-gleichgewicht":[{"type":"numeric","prompt":"Für H₂ + I₂ ⇌ 2 HI misst man im Gleichgewicht [H₂] = 0,20 mol/L, [I₂] = 0,20 mol/L und [HI] = 0,80 mol/L. Berechne die Gleichgewichtskonstante K (ohne Einheit).","answer":16,"tolerance":0.1,"explanation":"Nach dem Massenwirkungsgesetz gilt K = [HI]² / ([H₂] · [I₂]) = 0,64 / 0,04 = 16; K > 1 bedeutet, dass das Gleichgewicht auf der Seite des Produkts HI liegt.","difficulty":2}],"v76-smp-chemistry-04-saure-base-und-redox":[{"type":"mc","prompt":"In der Reaktion Zn + 2 Ag⁺ → Zn²⁺ + 2 Ag: Welche Aussage ist korrekt?","options":["Zink wird oxidiert (0 → +II), Silberionen werden reduziert (+I → 0).","Silberionen geben Elektronen ab und sind das Reduktionsmittel.","Zink wird reduziert (0 → +II), Silberionen werden oxidiert (+I → 0).","Es findet keine Elektronenübertragung statt, nur ein Protonenaustausch."],"answer":0,"explanation":"Die Oxidationszahl von Zink steigt von 0 auf +II, also gibt Zink Elektronen ab (Oxidation); die von Silber sinkt von +I auf 0, die Silberionen nehmen Elektronen auf (Reduktion).","difficulty":2}],"v76-smp-chemistry-05-organik":[{"type":"mc","prompt":"Welcher Kunststoff entsteht durch Polykondensation, also unter Abspaltung von Wasser?","options":["Polypropylen (PP)","Polyethylenterephthalat (PET)","Polyethylen (PE)","Polyvinylchlorid (PVC)"],"answer":1,"explanation":"PET ist ein Polyester und entsteht durch Polykondensation; PE, PP und PVC entstehen durch Polymerisation (Addition) von Monomeren mit Doppelbindung.","difficulty":2},{"type":"mc","prompt":"Warum werden gerade die Vorteile von Kunststoffen in der Umwelt zum Problem?","options":["Weil sie sich in Wasser rasch auflösen und das Wasser sauer machen","Weil sie beim Liegen an der Luft spontan zu Kohlenstoffdioxid verbrennen","Weil sie in der Natur schnell zu Erdöl zurückverwandelt werden","Weil sie sehr beständig sind, nur sehr langsam zerfallen und Mikroplastik bilden"],"answer":3,"explanation":"Die Beständigkeit, die Kunststoffe nützlich macht, bewirkt, dass sie in der Umwelt jahrzehntelang bleiben und in Mikroplastik zerfallen; darum sind Rezyklieren und Vermeiden wichtig.","difficulty":2}],"v76-smp-physics-01-mechanik":[{"type":"numeric","prompt":"Ein Stein fällt reibungsfrei aus 5,0 m Höhe aus der Ruhe. Wie gross ist seine Geschwindigkeit beim Aufprall? (m/s, g = 9,81 m/s²)","answer":9.9,"tolerance":0.1,"explanation":"Mit der Energieerhaltung m·g·h = ½·m·v² folgt v = √(2·9,81·5,0) ≈ 9,9 m/s, unabhängig von der Masse.","difficulty":2},{"type":"numeric","prompt":"Ein Lastwagen (2000 kg) mit 10 m/s prallt auf ein stehendes Auto (500 kg), beide verkeilen sich. Wie schnell bewegen sie sich danach? (m/s)","answer":8.0,"tolerance":0.1,"explanation":"Impulserhaltung beim unelastischen Stoss: 2000·10 = 2500·v, also v = 20 000 / 2500 = 8,0 m/s.","difficulty":2}],"v76-smp-physics-02-warmelehre":[{"type":"numeric","prompt":"Eine Gasmenge von 2,0 L bei 1,0 bar wird bei konstanter Temperatur auf 0,50 L zusammengedrückt. Wie gross ist der neue Druck? (bar)","answer":4.0,"tolerance":0.05,"explanation":"Nach Boyle-Mariotte bleibt p·V konstant: 1,0 · 2,0 = p · 0,50, also p = 4,0 bar.","difficulty":2},{"type":"mc","prompt":"Warum steigt der Druck eines Gases in einem geschlossenen Behälter, wenn man es erwärmt?","options":["Die Teilchen bewegen sich schneller und stossen häufiger und heftiger gegen die Wände","Die Anziehung zwischen den Teilchen nimmt zu und zieht an den Wänden","Die Teilchen werden beim Erwärmen grösser und füllen den Behälter stärker aus","Beim Erwärmen entstehen zusätzliche Gasteilchen aus der Behälterwand"],"answer":0,"explanation":"Nach der kinetischen Gastheorie ist die Temperatur ein Mass für die Bewegungsenergie der Teilchen; schnellere Teilchen übertragen bei Wandstössen mehr Impuls.","difficulty":2},{"type":"numeric","prompt":"Eine Wärmekraftmaschine arbeitet zwischen 600 K und 300 K. Wie gross ist ihr höchstmöglicher (Carnot-)Wirkungsgrad? (Prozent)","answer":50,"tolerance":0.5,"explanation":"η_C = 1 − T_k / T_w = 1 − 300 / 600 = 0,5, also 50 Prozent; reale Maschinen bleiben darunter.","difficulty":2}],"v76-smp-physics-03-elektrizitat-und-magnetismus":[{"type":"numeric","prompt":"Ein Wasserkocher nimmt an 230 V eine Leistung von 2000 W auf. Wie gross ist die Stromstärke? (A)","answer":8.7,"tolerance":0.1,"explanation":"Aus P = U · I folgt I = P / U = 2000 W / 230 V ≈ 8,7 A.","difficulty":2}],"v76-smp-physics-04-optik-und-wellen":[{"type":"mc","prompt":"Zwei gleich starke Schallwellen treffen mit einem Gangunterschied von einer halben Wellenlänge zusammen. Was geschieht?","options":["Sie werden vollständig reflektiert","Sie löschen sich aus (destruktive Interferenz)","Ihre Frequenz verdoppelt sich","Sie verstärken sich zur doppelten Amplitude"],"answer":1,"explanation":"Bei einem Gangunterschied von λ/2 trifft Wellenberg auf Wellental, die Auslenkungen heben sich auf; das nutzen Kopfhörer mit Geräuschunterdrückung.","difficulty":2}],"v76-smp-history-01-revolutionen-und-industrialisierung":[{"type":"mc","prompt":"Du sollst die Aussage «Die Französische Revolution war ein Erfolg» beurteilen. Welche Antwort erfüllt die Anforderungen?","options":["Sie zählt alle Ereignisse von 1789 bis 1799 in der richtigen Reihenfolge auf","Sie beschreibt nur die Hinrichtung Ludwigs XVI. möglichst ausführlich","Sie äussert eine klare persönliche Meinung ohne Belege, damit sie eindeutig ist","Sie nennt einen Massstab wie die Menschenrechte, wägt Errungenschaften und Terreur ab und zieht ein Fazit"],"answer":3,"explanation":"Ein Urteil braucht einen offengelegten Massstab, ein Sachurteil mit Belegen für beide Seiten und ein Fazit, das die Frage direkt beantwortet.","difficulty":2}],"v76-smp-history-02-nationalismus-und-imperialismus":[{"type":"mc","prompt":"Warum gilt die Schweiz als Willensnation und nicht als Kulturnation?","options":["Weil sie sich über eine gemeinsame Abstammung aller Kantone definiert","Weil sie durch Kriege eines Königs von oben geeint wurde","Weil sie trotz vier Landessprachen auf dem gemeinsamen politischen Willen zusammenzuleben beruht","Weil alle Einwohnerinnen und Einwohner dieselbe Sprache und Literatur teilen"],"answer":2,"explanation":"Eine Willensnation beruht auf dem gemeinsamen politischen Willen, nicht auf gemeinsamer Sprache; die mehrsprachige Schweiz ist dafür das Musterbeispiel.","difficulty":2},{"type":"mc","prompt":"Wie kam die deutsche Einigung von 1871 zustande?","options":["Durch einen Beschluss des Wiener Kongresses","Von unten durch eine siegreiche demokratische Revolution von 1848","Von oben durch Preussen unter Bismarck mit drei Kriegen und Diplomatie","Durch eine Volksabstimmung in allen deutschen Staaten"],"answer":2,"explanation":"Nach dem Scheitern der Revolution von 1848 einte Preussen Deutschland durch Kriege gegen Dänemark, Österreich und Frankreich; das Kaiserreich wurde in Versailles ausgerufen.","difficulty":2}],"v76-smp-history-03-weltkriege-und-totalitarismus":[{"type":"mc","prompt":"Womit lässt sich am besten begründen, dass die Weltwirtschaftskrise eine besonders wichtige Ursache für das Scheitern der Weimarer Republik war?","options":["Der Versailler Vertrag wurde 1919 unterzeichnet","Die Inflation erreichte 1923 ihren Höhepunkt","Hitler wurde am 30. Januar 1933 zum Reichskanzler ernannt","Die NSDAP stieg nach 1929 von 2,6 Prozent (1928) auf 37,3 Prozent im Juli 1932"],"answer":3,"explanation":"Eine Gewichtung braucht einen Beleg für die Wirkung: Erst mit der Krise und Millionen Arbeitslosen wurde die NSDAP zur Massenpartei.","difficulty":3}],"v76-smp-history-04-kalter-krieg-und-dekolonisation":[{"type":"mc","prompt":"Welche Ursache trug nach 1945 wesentlich zur Dekolonisation bei?","options":["Die Kolonialmächte waren durch den Zweiten Weltkrieg geschwächt, und die UNO-Charta anerkannte das Selbstbestimmungsrecht","Die Kolonien wurden durch den Marshallplan direkt in die Unabhängigkeit entlassen","Der Völkerbund verbot 1945 alle Kolonien","Die Sowjetunion besetzte die meisten afrikanischen Kolonien"],"answer":0,"explanation":"Geschwächte Kolonialmächte, starke Unabhängigkeitsbewegungen und das Selbstbestimmungsrecht der UNO-Charta waren zentrale Ursachen; der Kalte Krieg beschleunigte den Prozess nur.","difficulty":2},{"type":"numeric","prompt":"Im «Afrikanischen Jahr» wurden siebzehn afrikanische Staaten unabhängig. In welchem Jahr war das? (Jahr)","answer":1960,"tolerance":0,"explanation":"1960 wurden siebzehn Staaten unabhängig, die meisten ehemalige französische Kolonien; Ghana war 1957 vorangegangen.","difficulty":1}],"v76-smp-geography-01-geologie-und-klima":[{"type":"mc","prompt":"Aus Kalkstein wird unter hohem Druck und hoher Temperatur Marmor, ohne dass das Gestein schmilzt. Zu welcher Gesteinsgruppe gehört Marmor?","options":["Magmatische Tiefengesteine","Sedimentgesteine","Metamorphe Gesteine","Magmatische Ergussgesteine"],"answer":2,"explanation":"Metamorphe Gesteine entstehen durch Umwandlung unter Druck und Hitze ohne Aufschmelzen; aus Kalkstein wird Marmor, aus Granit Gneis.","difficulty":2},{"type":"numeric","prompt":"Südföhn: Luft hat auf 500 m 20 °C, steigt bis 2500 m und bildet ab 1000 m Wolken. Trockenadiabatisch ändert sich die Temperatur um 1 °C, feuchtadiabatisch um 0,5 °C pro 100 m; danach sinkt sie trocken auf 500 m. Endtemperatur? (°C)","answer":27.5,"tolerance":0.5,"explanation":"Aufstieg trocken bis 1000 m: 20 − 5 = 15 °C; feucht bis 2500 m: 15 − 7,5 = 7,5 °C; Abstieg trocken um 2000 m: 7,5 + 20 = 27,5 °C.","difficulty":3}],"v76-smp-geography-02-bevolkerung-und-migration":[{"type":"mc","prompt":"Eine Bevölkerungspyramide hat eine schmale Basis und eine breite Mitte (Urnenform). Was zeigt sie?","options":["Eine alternde Bevölkerung, die ohne Zuwanderung schrumpft","Eine junge, schnell wachsende Bevölkerung mit hoher Geburtenrate","Eine Bevölkerung mit besonders vielen Kindern unter 15 Jahren","Eine Bevölkerung in Phase 1 mit hohen Geburten- und Sterberaten"],"answer":0,"explanation":"Weniger Kinder als Erwachsene im mittleren Alter bedeuten tiefe Geburtenraten; ohne Zuwanderung schrumpft die Bevölkerung, wie in vielen europäischen Ländern.","difficulty":2},{"type":"mc","prompt":"Wer gilt nach der Genfer Flüchtlingskonvention von 1951 als Flüchtling?","options":["Wer wegen höherer Löhne in ein anderes Land zieht","Wer innerhalb seines Landes vom Land in die Stadt zieht","Wer wegen Ethnie, Religion, Nationalität, politischer Überzeugung oder sozialer Gruppe verfolgt wird","Wer für ein Studium befristet ins Ausland geht"],"answer":2,"explanation":"Die Konvention knüpft an Verfolgung aus bestimmten Gründen an; Arbeits-, Bildungs- und Binnenmigration sind freiwillige Formen der Migration.","difficulty":2}],"v76-smp-geography-03-siedlung-und-raumplanung":[{"type":"mc","prompt":"Familien ziehen in den 1970er-Jahren aus der Stadt Bern in Einfamilienhäuser im Umland. Welcher Prozess ist das?","options":["Reurbanisierung","Suburbanisierung","Landflucht","Gentrifizierung"],"answer":1,"explanation":"Bei der Suburbanisierung verlagern sich Wohnen und Betriebe aus der Kernstadt ins Umland; in Industrieländern geschah das besonders ab den 1950er- und 1960er-Jahren.","difficulty":2},{"type":"mc","prompt":"Was kennzeichnet informelle Siedlungen in Megastädten des globalen Südens?","options":["Selbst gebaute Unterkünfte oft ohne rechtliche Sicherheit, Kanalisation und sichere Lage","Villenviertel am Stadtrand für Pendlerinnen und Pendler","Ehemalige Industrieareale, die zu teuren Wohnungen umgebaut werden","Geplante Hochhausquartiere mit vollständiger Infrastruktur"],"answer":0,"explanation":"Weil Städte schneller wachsen als Wohnungen und Infrastruktur, bauen Zuwandernde selbst; diesen Siedlungen fehlen oft Landrechte, Wasser und Abwasser.","difficulty":2}],"v76-smp-geography-04-wirtschaft-und-globalisierung":[{"type":"mc","prompt":"Welche Energiequelle liefert in der Schweiz den grössten Teil der Stromproduktion?","options":["Windenergie mit rund der Hälfte","Erdgas mit rund drei Vierteln","Erdöl mit rund sechzig Prozent","Wasserkraft mit rund sechzig Prozent"],"answer":3,"explanation":"Die Wasserkraft ist die wichtigste einheimische Stromquelle; Erdöl und Erdgas werden importiert und vor allem für Verkehr und Heizungen genutzt.","difficulty":1}],"v76-smp-geography-05-entwicklung-und-nachhaltigkeit":[{"type":"mc","prompt":"Ein Land exportiert fast nur Kaffee und importiert teure Maschinen. Wie erklärt die Dependenztheorie seine Armut?","options":["Mit einer zu geringen Kaffeeproduktion im Vergleich zu den Nachbarn","Mit traditionellen Strukturen und fehlendem Kapital im Innern des Landes","Mit der Abhängigkeit vom Weltmarkt und ungleichen Tauschbeziehungen zwischen Zentrum und Peripherie","Mit einem zu hohen Human Development Index"],"answer":2,"explanation":"Die Dependenztheorie sucht die Ursachen aussen, in der Abhängigkeit seit der Kolonialzeit; innere Ursachen betont dagegen die Modernisierungstheorie.","difficulty":2},{"type":"tf","prompt":"Die siebzehn Ziele der Agenda 2030 gelten anders als die Millenniums-Entwicklungsziele für alle Länder, auch für die Schweiz.","options":["Richtig","Falsch"],"answer":0,"explanation":"Richtig: Die SDGs von 2015 verbinden soziale, wirtschaftliche und ökologische Ziele und verpflichten auch reiche Länder.","difficulty":1},{"type":"mc","prompt":"Was unterscheidet humanitäre Hilfe von langfristiger Entwicklungszusammenarbeit?","options":["Humanitäre Hilfe ist immer ein Kredit, Zusammenarbeit immer ein Geschenk","Es gibt keinen Unterschied, beide Begriffe meinen dasselbe","Humanitäre Hilfe wird nur von Staaten geleistet, Zusammenarbeit nur von Hilfswerken","Humanitäre Hilfe lindert akute Not nach Kriegen oder Katastrophen, Zusammenarbeit stärkt langfristig etwa Bildung und Gesundheit"],"answer":3,"explanation":"Humanitäre Hilfe reagiert auf akute Notlagen, Entwicklungszusammenarbeit setzt auf Hilfe zur Selbsthilfe in Bereichen wie Bildung, Gesundheit und Wasser.","difficulty":2}],"v76-smp-orientation-03-schriftliche-und-mundliche-prufungsform":[{"type":"mc","prompt":"Welches Fach wird an der Schweizerischen Maturitätsprüfung ausschliesslich mündlich geprüft?","options":["Geschichte","Das Schwerpunktfach","Das Ergänzungsfach","Mathematik"],"answer":2,"explanation":"Das Ergänzungsfach wird nur mündlich geprüft; Schwerpunktfach und Mathematik schriftlich und mündlich, Geschichte nur schriftlich.","difficulty":1},{"type":"tf","prompt":"Mathematik gehört an der SMP zur ersten Teilprüfung und wird nur schriftlich geprüft.","options":["Richtig","Falsch"],"answer":1,"explanation":"Falsch: Mathematik wird schriftlich und mündlich geprüft und gehört zur zweiten Teilprüfung; die erste umfasst Biologie, Chemie, Physik, Geschichte, Geografie sowie Bildnerisches Gestalten oder Musik.","difficulty":2}],"v76-bm-german-01-rezeption-und-textanalyse":[{"type":"mc","prompt":"In einem Kommentar steht: «Die Gemeinde sollte die Parkgebühren erhöhen, weil dann mehr Leute den Bus nehmen; in Bern stieg die Busnutzung nach einer Erhöhung um 12 Prozent.» Welche Funktion hat der Teil über Bern?","options":["Er ist ein normatives Argument, das sich auf Werte beruft","Er ist die These, die der Kommentar beweisen will","Er ist ein Gegenargument, das anschliessend entkräftet wird","Er ist der Beleg, der die Begründung mit einer Zahl stützt"],"answer":3,"explanation":"Ein vollständiges Argument hat Behauptung, Begründung und Beleg: Die Forderung ist die These, der Weil-Satz die Begründung, die Zahl aus Bern der Beleg (Faktenargument), kein Wert und kein Gegenargument.","difficulty":2}],"v76-bm-french-04-interkulturelle-kompetenz":[{"type":"mc","prompt":"Du triffst in Lausanne zum ersten Mal den etwa fünfzigjährigen Leiter deiner Praktikumsabteilung. Wie begrüsst du ihn am besten?","options":["Bonjour, tu vas bien, Monsieur ?","Bonjour Monsieur, vous allez bien ?","Salut, tu vas bien ?","Coucou, ça va ?"],"answer":1,"explanation":"Einen unbekannten Vorgesetzten siezt man und grüsst ihn mit Anrede; tu bleibt, bis er das du anbietet, und tu mit Monsieur mischt die Register.","difficulty":1}],"v76-bm-english-04-arbeits-und-studienkontexte":[{"type":"mc","prompt":"In an operating manual you read: «CAUTION: Wear gloves when removing the filter.» What does this warning level indicate?","options":["An optional recommendation without risk","An immediate danger of death","A risk of minor or moderate injury","Only possible damage to the machine"],"answer":2,"explanation":"Caution steht für ein geringeres Risiko, also leichte bis mittelschwere Verletzungen; Danger wäre unmittelbare Lebensgefahr, reiner Sachschaden heisst Notice.","difficulty":2},{"type":"mc","prompt":"In a meeting the discussion moves away from the agenda. Which phrase steers it back politely?","options":["Stop talking about that, please.","I'll put you through.","Please find attached the agenda.","Could we come back to that later? Let's move on to the next point."],"answer":3,"explanation":"Mit Could we come back to that later und Let's move on steuert man ein Meeting höflich; die anderen Sätze sind unhöflich oder gehören zu Telefon und E-Mail.","difficulty":1}],"v76-bm-math-02-gleichungen-und-funktionen":[{"type":"numeric","prompt":"2 Kaffees und 1 Gipfeli kosten 9.50 Franken, 1 Kaffee und 3 Gipfeli kosten 8.50 Franken. Was kostet ein Kaffee? (Franken)","answer":4,"tolerance":0.01,"explanation":"Aus 2k + g = 9.5 folgt g = 9.5 − 2k; eingesetzt in k + 3g = 8.5 ergibt sich −5k = −20, also k = 4 Franken (g = 1.50 Franken).","difficulty":2}],"v76-bm-math-04-geometrie-und-modellierung":[{"type":"numeric","prompt":"Eine Wand ist 5 m lang und 2,4 m hoch, ein Fenster von 1,5 m² wird nicht gestrichen. Ein Liter Farbe deckt 7 m². Wie viele Liter braucht es für zwei Anstriche? (Liter)","answer":3,"tolerance":0.01,"explanation":"Modell Rechteck minus Fenster: 5 · 2,4 − 1,5 = 10,5 m²; pro Anstrich 10,5 / 7 = 1,5 Liter, bei zwei Anstrichen also 3 Liter.","difficulty":2}],"v76-bm-focus-chemistry-01-stoffe-und-reaktionen":[{"type":"mc","prompt":"Ein Gemisch aus Wasser und Ethanol (Siedepunkt 78 °C) soll getrennt werden. Welches Verfahren eignet sich?","options":["Eindampfen, weil dabei nur das Wasser verdampft","Dekantieren, weil sich die Flüssigkeiten absetzen","Filtrieren, weil die Teilchen verschieden gross sind","Destillieren, weil sich die Siedepunkte unterscheiden"],"answer":3,"explanation":"Wasser und Ethanol sind mischbar und bilden ein homogenes Gemisch, das kein Filter und kein Absetzen trennt. Destillieren nutzt die unterschiedlichen Siedepunkte (78 °C gegenüber 100 °C); beim Eindampfen ginge auch das Ethanol verloren.","difficulty":2}],"v76-bm-focus-math-02-technische-modellierung":[{"type":"mc","prompt":"Das Akkumodell L(t) = 100 − 8t (L in Prozent, t in h) stammt aus Messungen zwischen 0 h und 10 h. Was gilt für eine Vorhersage bei t = 15 h?","options":["Der Akku zeigt nach 15 h noch 20 Prozent an.","Sie ist unbrauchbar: Das Modell ergibt −20 Prozent und gilt nur bis 12,5 h.","Sie ist eine Interpolation und deshalb besonders genau.","Sie ist zuverlässig, weil ein lineares Modell überall gilt."],"answer":1,"explanation":"100 − 8 · 15 = −20 Prozent ist unmöglich. t = 15 h liegt ausserhalb der Messdaten (Extrapolation), und das Modell gilt nur für 0 ≤ t ≤ 12,5 h.","difficulty":2},{"type":"numeric","prompt":"Ein Wassertank wird gleichmässig geleert. Nach 2 h enthält er 340 L, nach 5 h noch 220 L. Wie viele Liter enthielt er zu Beginn (t = 0)? (L)","answer":420,"tolerance":0.5,"explanation":"Lineares Modell: m = (220 − 340) / (5 − 2) = −40 L/h. Aus 340 = q − 40 · 2 folgt q = 420 L; das ist der Anfangsinhalt.","difficulty":2}],"v76-bm-focus-physics-01-mechanik":[{"type":"numeric","prompt":"Ein Auto fährt mit 72 km/h. Die Reaktionszeit beträgt 1 s, die Bremsverzögerung 8 m/s². Wie lang ist der Anhalteweg? (m)","answer":45,"tolerance":0.5,"explanation":"72 km/h = 20 m/s. Reaktionsweg 20 m/s · 1 s = 20 m, Bremsweg 20² / (2 · 8) = 25 m; der Anhalteweg ist die Summe, also 45 m.","difficulty":2}],"v76-bm-focus-physics-03-warme-und-wellen":[{"type":"numeric","prompt":"2 kg Wasser von 80 °C werden ohne Wärmeverluste mit 3 kg Wasser von 20 °C gemischt. Welche Mischtemperatur stellt sich ein? (°C)","answer":44,"tolerance":0.5,"explanation":"Abgegebene gleich aufgenommene Wärme: 2 · (80 − T) = 3 · (T − 20), also 160 + 60 = 5T und T = 44 °C. Das c von Wasser kürzt sich heraus.","difficulty":2}],"v76-bm-focus-math-03-geometrie-und-modellierung":[{"type":"numeric","prompt":"Eine zylindrische Dose soll 500 mL fassen und möglichst wenig Blech brauchen (optimal ist h = 2r). Wie gross ist ihr Radius? (cm, auf eine Dezimale)","answer":4.3,"tolerance":0.05,"explanation":"Mit h = 2r gilt V = 2πr³, also r = ∛(500 / (2π)) = ∛79,6 ≈ 4,3 cm; die Höhe ist dann rund 8,6 cm.","difficulty":3}],"v76-bm-focus-physics-05-energie-und-bauphysik":[{"type":"numeric","prompt":"Eine Aussenwand von 40 m² wird von U = 1,0 auf U = 0,2 W/(m²·K) gedämmt. Bei einer mittleren Temperaturdifferenz von 15 K und 5000 Heizstunden pro Jahr: Wie viel Heizenergie spart man jährlich? (kWh)","answer":2400,"tolerance":1,"explanation":"Die Verlustleistung sinkt um ΔP = (1,0 − 0,2) · 40 · 15 = 480 W. Über 5000 h sind das 480 W · 5000 h = 2 400 000 Wh = 2400 kWh.","difficulty":3}],"v76-bm-focus-chemistry-03-stoffe-reaktionen-und-gleichgewichte":[{"type":"mc","prompt":"Warum reagiert Kalkpulver mit Salzsäure schneller als ein gleich schweres Stück Kalkstein?","options":["Das Pulver senkt die Aktivierungsenergie wie ein Katalysator.","Das Pulver enthält mehr Calciumcarbonat-Teilchen als das Stück.","Das Pulver verschiebt das Gleichgewicht zu den Produkten.","Das Pulver hat eine grössere Oberfläche, darum stossen pro Sekunde mehr Teilchen zusammen."],"answer":3,"explanation":"Die Masse und damit die Teilchenzahl sind gleich. Beim Pulver liegen aber viel mehr Teilchen an der Oberfläche, wo die Säure angreifen kann; das erhöht die Zahl der wirksamen Zusammenstösse.","difficulty":2},{"type":"tf","prompt":"Ein Katalysator beschleunigt Hin- und Rückreaktion gleich stark und verändert die Lage des Gleichgewichts nicht.","options":["Richtig","Falsch"],"answer":0,"explanation":"Der Katalysator senkt die Aktivierungsenergie für beide Richtungen. Das Gleichgewicht stellt sich schneller ein, K und die Ausbeute bleiben aber gleich.","difficulty":2}],"v76-bm-focus-biology-03-okologie-genetik-und-physiologie":[{"type":"mc","prompt":"Nach jahrelangem Einsatz eines Insektizids sind fast alle Kartoffelkäfer eines Gebiets dagegen resistent. Wie erklärst du das?","options":["Das Insektizid hat bei den Käfern gezielt die passende Resistenzmutation ausgelöst","Einzelne Käfer trugen durch Mutation ein Resistenzallel; sie überlebten, vermehrten sich häufiger, und das Allel wurde häufiger","Die Neukombination der Allele hat ohne Selektion zufällig nur resistente Käfer erzeugt","Jeder Käfer hat sich im Lauf seines Lebens an das Gift gewöhnt und die Gewöhnung vererbt"],"answer":1,"explanation":"Mutationen entstehen zufällig und nicht gezielt. Das Insektizid wirkt als Selektionsfaktor: Resistente Tiere überleben und vermehren sich häufiger, darum nimmt ihr Allel in der Population zu. Erworbene Gewöhnung wird nicht vererbt.","difficulty":2}],"v76-bm-focus-physics-07-mechanik-energie-und-umweltanwendungen":[{"type":"numeric","prompt":"Eine Photovoltaikanlage hat 20 m² Modulfläche und einen Wirkungsgrad von 20 %. Welche elektrische Leistung liefert sie bei voller Sonne mit 1 000 W/m²? (kW)","answer":4,"tolerance":0.05,"explanation":"P = η · Einstrahlung · A = 0,2 · 1 000 W/m² · 20 m² = 4 000 W = 4 kW.","difficulty":1}],"v76-bm-focus-economics-03-betriebswirtschaft-und-recht":[{"type":"mc","prompt":"Zwei Freundinnen gründen eine Firma. Sie wollen nicht mit ihrem Privatvermögen haften und können zusammen 30 000 Franken Kapital einbringen. Welche Rechtsform passt?","options":["AG, weil 30 000 Franken als Aktienkapital ausreichen","Zwei Einzelunternehmen, weil dann jede nur für sich haftet","GmbH, weil die Gesellschaft haftet und 20 000 Franken Stammkapital genügen","Kollektivgesellschaft, weil sie kein Mindestkapital verlangt"],"answer":2,"explanation":"In der GmbH haftet nur das Gesellschaftsvermögen, das Mindestkapital beträgt 20 000 Franken. Die AG verlangt 100 000 Franken; bei Kollektivgesellschaft und Einzelunternehmen haften die Inhaberinnen persönlich und unbeschränkt.","difficulty":2}],"v76-bm-focus-history-01-geschichte-und-politik":[{"type":"mc","prompt":"Welche Aufgabe übernimmt in der Schweiz nach dem Grundsatz der Subsidiarität typischerweise die Gemeinde?","options":["Landesverteidigung","Wasserversorgung und Abfallentsorgung","Geld und Währung","Zoll an der Landesgrenze"],"answer":1,"explanation":"Subsidiarität heisst: Die tiefste Ebene, die eine Aufgabe gut erfüllen kann, übernimmt sie. Wasser und Abfall regelt die Gemeinde; Armee, Währung und Zoll weist die Bundesverfassung dem Bund zu.","difficulty":1}],"v76-bm-focus-communication-01-information-und-kommunikation":[{"type":"mc","prompt":"Im Klassenchat wird ein Foto einer überfluteten Strasse mit dem Text Heute in Zürich geteilt. Welcher Schritt prüft am besten, ob das Bild wirklich aktuell ist?","options":["Zählen, wie oft das Bild im Chat schon weitergeleitet wurde","Mit einer umgekehrten Bildersuche nachsehen, wann und wo das Bild zuerst erschien","Auf die Bildqualität achten, denn scharfe Bilder sind immer echt","Das Bild weiterleiten und fragen, ob jemand etwas dazu weiss"],"answer":1,"explanation":"Die umgekehrte Bildersuche zeigt Datum und Zusammenhang der ersten Veröffentlichung; häufiges Teilen oder gute Bildqualität beweisen nichts über die Aktualität.","difficulty":2}],"v76-bm-focus-biology-04-biologie-und-gesundheit":[{"type":"mc","prompt":"Welche Aussage beschreibt die spezifische Abwehr im Unterschied zur unspezifischen Abwehr richtig?","options":["B-Zellen bilden Antikörper gegen ein bestimmtes Antigen, und es entstehen Gedächtniszellen","Fieber und Entzündung wirken sofort gegen alle Erreger gleich","Fresszellen nehmen jeden Fremdkörper sofort auf, ohne ihn genau zu erkennen","Haut und Schleimhäute halten Erreger als mechanische Barriere zurück"],"answer":0,"explanation":"Spezifisch heisst gezielt gegen ein bestimmtes Antigen: B-Zellen bilden Antikörper, T-Zellen töten befallene Zellen; Fresszellen, Barrieren, Fieber und Entzündung gehören zur unspezifischen Abwehr.","difficulty":2}],"v76-bm-focus-physics-08-physik-im-gesundheitskontext":[{"type":"numeric","prompt":"Ein Blutdruck von 120 mmHg soll in Kilopascal angegeben werden (1 mmHg ≈ 133 Pa). Wie gross ist er? (kPa, auf eine Dezimale)","answer":16.0,"tolerance":0.1,"explanation":"120 · 133 Pa = 15 960 Pa ≈ 16,0 kPa. Gemeint ist der Überdruck gegenüber dem Luftdruck.","difficulty":1}],"v76-bm-focus-economics-04-wirtschaft-und-recht":[{"type":"mc","prompt":"Welche Steuer ist eine indirekte Steuer, die im Preis enthalten ist und von den Konsumenten getragen wird?","options":["Einkommenssteuer","Vermögenssteuer","Mehrwertsteuer","Direkte Bundessteuer"],"answer":2,"explanation":"Die Mehrwertsteuer liefert der Verkäufer ab, getragen wird sie aber über den Preis von den Konsumenten; Einkommens-, Vermögens- und direkte Bundessteuer werden direkt bei der steuerpflichtigen Person erhoben.","difficulty":1}],"v76-ebmp-de-01-schriftliche-textproduktion-und-analyse":[{"type":"mc","prompt":"Du schreibst einen Textvergleich zwischen Haupttext und Vergleichstext. Womit beginnst du den Hauptteil am sinnvollsten?","options":["Mit einer Nacherzählung des Haupttextes und danach einer Nacherzählung des Vergleichstextes","Mit dem gemeinsamen Thema und den Ansichten, in denen sich die beiden Texte gleichen oder unterscheiden","Mit deiner eigenen Meinung zum Thema, ohne die Texte zu erwähnen","Mit einer Liste aller sprachlichen Mittel des Vergleichstextes"],"answer":1,"explanation":"Ein Vergleich ordnet beide Texte nach Vergleichspunkten wie Thema und Ansicht; blosse Nacherzählungen oder eine Meinung ohne Textbezug vergleichen nichts, die persönliche Auseinandersetzung folgt erst danach.","difficulty":2},{"type":"mc","prompt":"Du gliederst eine Kurzgeschichte in logische Abschnitte. Woran erkennst du am ehesten, dass ein neuer Abschnitt beginnt?","options":["Im Text taucht ein neues sprachliches Mittel auf","Ort, Zeit, beteiligte Figuren oder die Handlung ändern sich deutlich","Im Druckbild beginnt ein neuer Absatz","Es sind wieder etwa zehn Zeilen vergangen"],"answer":1,"explanation":"Logische Abschnitte folgen dem Inhalt: Ein Wechsel von Ort, Zeit, Figuren oder Handlung markiert einen neuen Abschnitt. Gedruckte Absätze, einzelne Stilmittel oder eine feste Zeilenzahl sagen darüber nichts Verlässliches.","difficulty":2}],"v76-ebmp-de-02-mundliche-literaturprufung":[{"type":"mc","prompt":"Was gehört in der mündlichen Literaturprüfung zum gestaltenden Vorlesen der gewählten Textpassage?","options":["Laut und deutlich lesen, an Satzzeichen Pausen setzen und die Stimmung der Stelle hörbar machen","Eine beliebige Stelle lesen, die mit dem Exposé nichts zu tun hat","Möglichst schnell lesen, damit mehr Zeit für das Exposé bleibt","Die Passage frei nacherzählen, statt sie wörtlich vorzulesen"],"answer":0,"explanation":"Verlangt ist lautes, deutliches und gestaltendes Vorlesen; Tempo, Pausen und Betonung machen die Stelle verständlich, und sie bildet den Ausgangspunkt des Exposés.","difficulty":1}],"v76-ebmp-de-03-sechs-werke-nach-auswahlregeln":[{"type":"mc","prompt":"Eine Werkliste enthält: zwei Dramen vor 1900, drei Romane ab 1900 und einen Gedichtband ab 1900. Erfüllt sie die amtlichen Auswahlregeln?","options":["Ja: zwei Werke vor 1900, vier ab 1900, Epik, Dramatik und Lyrik sind vertreten","Nein: vor 1900 fehlt ein Werk der Epik","Nein: es braucht drei Werke vor 1900","Nein: Lyrik darf nicht gewählt werden"],"answer":0,"explanation":"Verlangt sind zwei Werke vor 1900 und vier ab 1900; jede Gattung muss insgesamt mindestens einmal vorkommen, nicht in jeder Epoche. Romane zählen zur Epik, Dramen zur Dramatik, der Gedichtband zur Lyrik.","difficulty":2}],"v76-ebmp-fr-01-hor-oder-seh-horverstehen":[{"type":"mc","prompt":"Aussage: «Le train a vingt minutes de retard.» Du hörst: «Le train partira avec dix minutes de retard.» Wie löst du die Richtig/Falsch-Aufgabe vollständig?","options":["Vrai, mit der Begründung: Le train part avec du retard.","Vrai, weil der Zug tatsächlich Verspätung hat","Faux, ohne Begründung, weil ein Kreuz genügt","Faux, mit der Begründung: Le train a dix minutes de retard."],"answer":3,"explanation":"Die Verspätung beträgt zehn, nicht zwanzig Minuten; die Aussage ist also falsch, und die Begründung nennt die gehörte Information.","difficulty":2}],"v76-ebmp-en-01-hor-oder-seh-horverstehen":[{"type":"mc","prompt":"Aussage: «The library opens at eight today.» Du hörst: «The library will open at ten instead of eight.» Wie löst du die Richtig/Falsch-Aufgabe vollständig?","options":["True, because the word eight is in the recording.","False, because the library opens at ten today.","True, because the library opens today.","False, without a reason, because the cross is enough."],"answer":1,"explanation":"Gehört wird, dass die Bibliothek um zehn statt um acht öffnet; die Aussage ist also falsch, und die Begründung nennt die gehörte Uhrzeit.","difficulty":2},{"type":"mc","prompt":"Frage: «How will Tom travel to Geneva?» Du hörst: «I wanted to take the car, but it is broken, so I am taking the train.» Welche Antwort ist richtig?","options":["By bus","By car","By plane","By train"],"answer":3,"explanation":"Das Auto wird zuerst genannt, ist aber ein Ablenker: Es ist kaputt, und nach so folgt die gültige Information, der Zug.","difficulty":2}],"v76-ebmp-en-02-textverstandnis":[{"type":"tf","prompt":"Bei einer Richtig/Falsch-Aufgabe mit Antwortbegründung genügt es, false anzukreuzen, wenn man sich sicher ist.","options":["Richtig","Falsch"],"answer":1,"explanation":"Verlangt ist zusätzlich eine Begründung mit der passenden Textstelle; ohne Beleg ist die Aufgabe nicht vollständig gelöst.","difficulty":1}],"v76-ebmp-math-01-grundlagenbereich-mathematik":[{"type":"numeric","prompt":"Taxi A kostet 8 Franken Grundtaxe plus 2 Franken pro km, Taxi B 14 Franken Grundtaxe plus 1.50 Franken pro km. Bei wie vielen Kilometern kosten beide gleich viel (km)?","answer":12,"tolerance":0,"explanation":"8 + 2x = 14 + 1,5x ergibt 0,5x = 6, also x = 12 km; Probe: Beide Fahrten kosten 32 Franken.","difficulty":2}],"v76-ebmp-math-02-schwerpunkt-mathematik-tals":[{"type":"numeric","prompt":"Ein Kapital von 8 000 Franken wird 3 Jahre zu 2 % mit Zinseszins angelegt. Wie gross ist das Endkapital (in Franken)?","answer":8489.66,"tolerance":0.5,"explanation":"K = 8 000 · 1,02³ = 8 000 · 1,061208 ≈ 8 489,66 Franken; die Zinsen werden jedes Jahr mitverzinst, daher der Faktor hoch drei.","difficulty":2}],"v76-ebmp-phys-01-mechanik-und-energie":[{"type":"numeric","prompt":"Ein Auto mit 1 000 kg bremst gleichmässig in 5 s von 25 m/s bis zum Stillstand. Wie gross ist der Betrag der Bremskraft (in N)?","answer":5000,"tolerance":0,"explanation":"a = Δv / t = 25 m/s : 5 s = 5 m/s²; nach dem zweiten newtonschen Gesetz ist F = m · a = 1 000 kg · 5 m/s² = 5 000 N.","difficulty":2}],"v76-ebmp-chem-01-stoffe-und-reaktionen":[{"type":"mc","prompt":"Welcher der folgenden Stoffe ist ein Gemisch und kein Reinstoff?","options":["Messing","destilliertes Wasser","Kohlendioxid","Magnesium"],"answer":0,"explanation":"Messing ist eine Legierung aus Kupfer und Zink, also ein Gemisch; die anderen Stoffe sind Reinstoffe mit festen Eigenschaften.","difficulty":1}],"v76-ebmp-wr-02-volkswirtschaft":[{"type":"numeric","prompt":"Das nominale BIP wächst um 4 %, die Teuerung gemäss LIK beträgt 1,5 %. Wie gross ist das reale Wachstum näherungsweise (in Prozent)?","answer":2.5,"tolerance":0.05,"explanation":"Reales Wachstum ist näherungsweise nominales Wachstum minus Inflation: 4 % − 1,5 % = 2,5 %. Nur dieser Teil zeigt eine tatsächlich grössere Produktion.","difficulty":2},{"type":"mc","prompt":"Die Schweiz steckt in einer Rezession. Welche Massnahme entspricht einer antizyklischen Fiskalpolitik?","options":["Der Staat kürzt sofort die Ausgaben, damit kein Defizit entsteht","Der Staat investiert mehr in Infrastruktur oder senkt Steuern, um die Nachfrage zu stützen","Die SNB erhöht den Leitzins, um die Teuerung zu bremsen","Der Staat erhöht die Steuern, um in der Rezession Überschüsse zu bilden"],"answer":1,"explanation":"Antizyklisch heisst gegen die Konjunktur: In der Rezession stützt der Staat die Nachfrage mit Ausgaben oder Steuersenkungen. Der Leitzins gehört zur Geldpolitik der SNB, nicht zur Fiskalpolitik.","difficulty":2}],"v76-ebmp-wr-03-privat-und-gesellschaftsrecht":[{"type":"mc","prompt":"Drei Freundinnen gründen eine Webdesign-Firma. Sie haben zusammen 25 000 Franken und wollen nicht mit ihrem Privatvermögen haften. Welche Rechtsform passt am besten?","options":["GmbH, weil das Mindestkapital von 20 000 Franken erreicht ist und grundsätzlich nur das Gesellschaftsvermögen haftet","Einzelunternehmen, weil es ohne Kapital sofort gegründet werden kann","AG, weil nur bei der AG die Haftung auf das Gesellschaftsvermögen beschränkt ist","Kollektivgesellschaft, weil sie kein Mindestkapital verlangt und das Privatvermögen schützt"],"answer":0,"explanation":"Die GmbH verlangt 20 000 Franken, die AG 100 000 Franken Mindestkapital. In der Kollektivgesellschaft und im Einzelunternehmen haften die Gründer unbeschränkt mit dem Privatvermögen.","difficulty":2}],"v76-ebmp-wr-04-falllosung-und-urteil":[{"type":"mc","prompt":"Lara verlangt wegen eines defekten Velos Gewährleistung nach Art. 197 und 201 OR. Was heisst es, diese Normen in ihre Voraussetzungen zu zerlegen?","options":["Die einzelnen Tatbestandsmerkmale auflisten: Kaufvertrag, Mangel, rechtzeitige Prüfung und sofortige Mängelrüge","Die Rechtsfolge Wandelung oder Minderung direkt aus dem Sachverhalt ablesen","Im Sachverhalt alle Personen, Daten und Beträge mit dem Stift markieren","Zuerst das Ergebnis nennen und es danach mit dem Gesetz begründen"],"answer":0,"explanation":"Zerlegen heisst, die Norm in ihre Tatbestandsmerkmale aufzuteilen, die danach einzeln subsumiert werden. Markieren gehört zum ersten Schritt, das Ergebnis zuerst zu nennen ist Urteilsstil.","difficulty":2}],"v76-ebmp-idpa-02-interdisziplinare-bearbeitung":[{"type":"numeric","prompt":"Sieben Lernende nennen ihren Arbeitsweg in Minuten: 8, 25, 12, 60, 15, 10, 20. Wie gross ist der Median (in Minuten)?","answer":15,"tolerance":0,"explanation":"Geordnet lautet die Reihe 8, 10, 12, 15, 20, 25, 60; der mittlere, vierte Wert ist 15. Der Mittelwert läge wegen des Extremwerts 60 höher, bei 150 : 7 ≈ 21,4 Minuten.","difficulty":2}],"v76-ebmp-bio-01-zellen-und-genetik":[{"type":"mc","prompt":"Welche Aussage vergleicht Mitose und Meiose beim Menschen richtig?","options":["Beide Teilungen halbieren den Chromosomensatz von 46 auf 23","Die Mitose liefert zwei gleiche diploide Körperzellen mit 46 Chromosomen, die Meiose vier haploide Keimzellen mit 23 Chromosomen","Die Mitose liefert vier haploide Keimzellen, die Meiose zwei gleiche Körperzellen","Die Meiose dient dem Wachstum und der Wundheilung, die Mitose der Fortpflanzung"],"answer":1,"explanation":"Die Mitose erhält den diploiden Satz und dient Wachstum und Reparatur. Die Meiose halbiert ihn in zwei Teilungen, sodass bei der Befruchtung wieder 46 Chromosomen entstehen.","difficulty":1}],"v76-ebmp-frw-02-kostenrechnung-und-nutzschwelle":[{"type":"numeric","prompt":"Ein Produkt kostet 80 Franken, die variablen Kosten betragen 52 Franken pro Stück. Wie gross ist die Deckungsbeitragsmarge (in Prozent)?","answer":35,"tolerance":0,"explanation":"Der Deckungsbeitrag beträgt 80 − 52 = 28 Franken, die Marge 28 : 80 = 0,35 = 35 %. Von jedem Umsatzfranken bleiben 35 Rappen zur Deckung der Fixkosten.","difficulty":1}],"v76-ebmp-social-01-soziologie":[{"type":"mc","prompt":"Im Team ist es üblich, sich am Morgen zu grüssen. Wer es nicht tut, wird von den anderen schief angeschaut. Wie lässt sich diese Norm einordnen?","options":["Als Muss-Norm, deren Verletzung nach Gesetz bestraft wird","Als Wert, weil Grüssen eine grundlegende Vorstellung des Erstrebenswerten ist","Als Soll-Norm, die mit einer negativen Sanktion durchgesetzt wird","Als Kann-Norm, deren Verletzung keinerlei Reaktion auslöst"],"answer":2,"explanation":"Grüssen wird stark erwartet, ist aber nicht gesetzlich geregelt, darum ist es eine Soll-Norm; das schiefe Anschauen ist eine negative Sanktion, weil es das unerwünschte Verhalten missbilligt.","difficulty":2}],"v76-ebmp-social-03-philosophie-und-ethik":[{"type":"mc","prompt":"In welcher Reihenfolge baust du ein ethisches Argument zu einer Streitfrage vollständig auf?","options":["These, Begründung mit Massstab, Gegenargument, Abwägung, Fazit","Begründung, Gegenargument, These, Fazit, Abwägung","These, Fazit, Begründung, Beispiel, Quellenangabe","Fazit, These, Beispiel, Begründung, Gegenargument"],"answer":0,"explanation":"Zuerst steht die These als Antwort auf die Frage, dann die Begründung mit einem Massstab; erst nach Gegenargument und Abwägung folgt das Fazit.","difficulty":1}],"v76-ebmp-social-04-fall-und-quellenanalyse":[{"type":"mc","prompt":"Ein Lernender verschweigt im Meeting einen Fehler im Plan, weil alle anderen zustimmen. Welcher Satz ist ein begründetes Urteil mit ausdrücklichem Massstab?","options":["Das Verhalten ist einfach schlecht und darf nicht vorkommen.","Im Meeting stimmten alle dem Plan zu, und der Lernende sagte nichts.","Der Lernende schwieg, weil die Mehrheit dem Plan bereits zugestimmt hatte.","Das Schweigen ist wegen des Gruppendrucks verständlich, gemessen an der Sorgfaltspflicht aus dem Arbeitsvertrag aber nicht gerechtfertigt, weil der Fehler dem Betrieb schadet."],"answer":3,"explanation":"Nur der erste Satz trennt Verstehen und Rechtfertigen und nennt mit der Sorgfaltspflicht einen überprüfbaren Massstab; die anderen Sätze deuten nur, werten ohne Massstab oder fassen bloss zusammen.","difficulty":2}],"v76-ebmp-arts-02-praktische-arbeit":[{"type":"numeric","prompt":"Du hast für eine praktische Arbeit 40 Lektionen und teilst sie im Verhältnis des Richtbeispiels 5 : 15 : 6 : 4 (Tests, Ausführung, Überarbeitung, Dokumentation) ein. Wie viele Lektionen planst du für die Ausführung? (Lektionen)","answer":20,"tolerance":0,"explanation":"Die Ausführung umfasst 15 von 30 Lektionen, also die Hälfte der Zeit; die Hälfte von 40 Lektionen sind 20 Lektionen.","difficulty":2}],"v76-ebmp-ic-01-recherche-und-quellen":[{"type":"mc","prompt":"Welche Angaben gehören in ein einfaches Rechercheprotokoll, damit deine Suche später nachvollziehbar ist?","options":["Eine Zusammenfassung jeder gelesenen Quelle, aber keine Suchbegriffe","Nur die Quellen, die du am Schluss in der Arbeit zitierst","Die Anzahl Treffer jeder Suche und die Dauer der Suche","Datum, Suchbegriffe, Suchort, gefundene Quelle und eine kurze Beurteilung"],"answer":3,"explanation":"Das Protokoll hält fest, womit und wo gesucht wurde und wie die Quelle beurteilt wurde; nur so kannst du später begründen, warum du eine Quelle verwendet oder verworfen hast.","difficulty":1}],"v76-fms-french-01-rezeption":[{"type":"mc","prompt":"Im Text steht: «Le musée est petit, mais la collection est magnifique.» Was betont die Person mit diesem Satz?","options":["Dass das Museum gross und berühmt ist.","Dass sie vom Besuch des Museums abrät.","Dass sich der Besuch wegen der Sammlung lohnt.","Dass das Museum leider zu klein ist."],"answer":2,"explanation":"Nach mais folgt meist die wichtigere Information: Die geringe Grösse wird nur eingeräumt, die prächtige Sammlung ist die eigentliche Aussage.","difficulty":2}],"v76-fms-english-03-produktion-und-kultur":[{"type":"mc","prompt":"Du musst die Einladung deiner englischen Gastfamilie für Samstag absagen. Welche Formulierung entspricht der üblichen indirekten Höflichkeit?","options":["Saturday is impossible for me.","That sounds lovely, but I'm afraid I can't make it on Saturday.","I don't want to come on Saturday.","No, I can't come on Saturday."],"answer":1,"explanation":"Indirekte Wendungen wie That sounds lovely mit I'm afraid mildern die Absage; die anderen Sätze sind grammatisch korrekt, wirken aber direkt oder sogar unhöflich.","difficulty":2}],"v76-fms-math-01-arithmetik-und-algebra":[{"type":"numeric","prompt":"Die Trapezformel A = (a + c) / 2 · h soll nach h umgestellt werden. Ein Trapez hat A = 30 cm², a = 7 cm und c = 5 cm. Wie gross ist h? (cm)","answer":5,"tolerance":0,"explanation":"Umgestellt gilt h = 2 · A / (a + c) = 60 / 12 = 5 cm; die Probe (7 + 5) / 2 · 5 = 30 bestätigt das Ergebnis.","difficulty":2}],"v76-fms-math-02-funktionen-und-geometrie":[{"type":"numeric","prompt":"Ein Aquarium ist 60 cm lang, 30 cm breit und 40 cm hoch. Wie viele Liter Wasser fasst es ganz gefüllt? (Liter)","answer":72,"tolerance":0,"explanation":"V = 6 dm · 3 dm · 4 dm = 72 dm³, und 1 dm³ entspricht 1 Liter; wer in cm³ rechnet, erhält 72 000 cm³ und muss noch durch 1000 teilen.","difficulty":2}],"v76-fms-biology-03-okologie-und-gesundheit":[{"type":"mc","prompt":"Welche Rolle übernehmen Pilze und Regenwürmer in einem Waldökosystem?","options":["Sie sind Produzenten und bauen mit Lichtenergie Zucker auf.","Sie sind Destruenten und zersetzen tote Lebewesen zu Mineralstoffen für die Pflanzen.","Sie sind abiotische Faktoren wie Licht und Temperatur.","Sie sind Konsumenten zweiter Ordnung und fressen Pflanzenfresser."],"answer":1,"explanation":"Destruenten schliessen den Stoffkreislauf, weil sie totes Material abbauen und die Mineralstoffe den Produzenten wieder zur Verfügung stellen.","difficulty":1}],"v76-fms-chemistry-01-stoffe-und-reaktionen":[{"type":"mc","prompt":"Ein Gemisch aus Sand, Kochsalz und Wasser soll getrennt werden. Welche Reihenfolge der Trennverfahren ist sinnvoll?","options":["Nur abwarten, weil sich Salz und Sand von selbst am Boden absetzen.","Nur filtrieren, weil auch das gelöste Salz im Filter hängen bleibt.","Zuerst das Wasser verdampfen, dann filtrieren, damit das Salz im Filter bleibt.","Zuerst filtrieren, damit der Sand im Filter bleibt, dann das Wasser verdampfen, damit das Salz zurückbleibt."],"answer":3,"explanation":"Sand ist unlöslich und bleibt im Filter; das gelöste Salz geht mit dem Wasser durch den Filter und bleibt erst beim Verdampfen zurück.","difficulty":2}],"v76-fms-chemistry-02-chemie-im-alltag-und-berufsfeld":[{"type":"numeric","prompt":"Aus einem Konzentrat sollen 2 Liter einer 2-prozentigen Gebrauchslösung hergestellt werden. Wie viel Konzentrat brauchst du? (ml)","answer":40,"tolerance":0,"explanation":"2 % von 2000 ml sind 0,02 · 2000 = 40 ml Konzentrat; die übrigen 1960 ml sind Wasser.","difficulty":2}],"v76-fms-physics-01-mechanik-und-energie":[{"type":"numeric","prompt":"Ein Ball fällt ohne Luftwiderstand aus 3,2 m Höhe. Mit welcher Geschwindigkeit trifft er auf, wenn du mit g = 10 m/s² rechnest? (m/s)","answer":8,"tolerance":0.1,"explanation":"Nach dem Energieerhaltungssatz wird die Lageenergie m · g · h ganz zu ½ · m · v²; die Masse kürzt sich, also v = √(2 · 10 · 3,2) = √64 = 8 m/s.","difficulty":3},{"type":"numeric","prompt":"Eine Velofahrerin hat mit ihrem Velo zusammen eine Masse von 80 kg und beschleunigt mit 1,5 m/s². Wie gross ist die dafür nötige resultierende Kraft? (N)","answer":120,"tolerance":0,"explanation":"Nach dem zweiten Newtonschen Gesetz gilt F = m · a = 80 kg · 1,5 m/s² = 120 N.","difficulty":1}],"v76-fms-physics-02-elektrizitat-und-technische-anwendungen":[{"type":"numeric","prompt":"Ein Föhn mit 1500 W läuft jeden Tag 10 Minuten. Wie viel kostet das in 30 Tagen bei 0,30 Franken pro kWh? (Franken)","answer":2.25,"tolerance":0.01,"explanation":"10 Minuten sind 1/6 Stunde, also 1,5 kW · 1/6 h = 0,25 kWh pro Tag; in 30 Tagen sind das 7,5 kWh, mal 0,30 Franken ergibt 2,25 Franken.","difficulty":2}],"v76-fms-geography-01-raum-und-umwelt":[{"type":"mc","prompt":"Durch welchen Vorgang sind die Alpen als Faltengebirge entstanden?","options":["Zwei Platten bewegten sich auseinander, und das Land dazwischen hob sich.","Die Adriatische Platte schob sich gegen die Europäische Platte, Gesteinsschichten wurden gefaltet und gehoben.","Eiszeitliche Gletscher haben das Gestein zu Bergen aufgetürmt.","Vulkane haben über Jahrmillionen Lava zu Bergen aufgeschichtet."],"answer":1,"explanation":"Die Alpen sind ein Kollisionsgebirge: Beim Zusammenstoss der Platten wurden Meeresablagerungen gefaltet, zu Decken übereinandergeschoben und gehoben; Gletscher formten die Täler erst später.","difficulty":2}],"v76-fms-geography-03-nachhaltigkeit":[{"type":"mc","prompt":"Eine Gemeinde plant ein neues Wasserkraftwerk an einem Bergbach. Welche Aussage benennt den Zielkonflikt korrekt?","options":["Das Kraftwerk schadet allen drei Dimensionen gleichzeitig.","Es gibt keinen Zielkonflikt, weil Wasserkraft erneuerbar ist.","Der Zielkonflikt besteht nur zwischen Gesellschaft und Wirtschaft.","Der Strom ist erneuerbar, aber der Eingriff verändert den Bach als Lebensraum."],"answer":3,"explanation":"Ein Zielkonflikt liegt vor, wenn eine Massnahme einer Dimension nützt und einer anderen schadet: Hier nützt sie dem Klima, schadet aber Flüssen und Lebensräumen.","difficulty":2}],"v76-fms-economics-03-fallbezug":[{"type":"mc","prompt":"Mia verdient netto 3800 Franken. Fixe Ausgaben 2100, variable Ausgaben 1300, Rückstellungen 500 Franken pro Monat. Wie ist ihr Budget zu beurteilen?","options":["Es geht genau auf, weil Rückstellungen nicht zu den Ausgaben zählen.","Es geht auf: Es bleiben 400 Franken übrig.","Es geht nicht auf: Es fehlen 100 Franken pro Monat.","Es bleiben 200 Franken übrig, die gespart werden können."],"answer":2,"explanation":"Ausgaben und Rückstellungen ergeben 2100 + 1300 + 500 = 3900 Franken, also 100 Franken mehr als der Nettolohn; Rückstellungen müssen mitgerechnet werden.","difficulty":2}],"v76-fms-informatics-01-daten-und-algorithmen":[{"type":"mc","prompt":"In der Datenbank einer Kita gibt es zwei Kinder namens Lara Meier. Was verhindert am zuverlässigsten, dass eine Allergie dem falschen Kind zugeordnet wird?","options":["Die binäre Suche nach dem Namen","Die alphabetische Sortierung der Liste","Eine eindeutige Kennnummer pro Kind","Eine zusätzliche Spalte mit dem Vornamen"],"answer":2,"explanation":"Nur eine eindeutige Kennnummer unterscheidet Personen mit gleichem Namen sicher; Sortieren oder Suchen ändern nichts an der Verwechslungsgefahr.","difficulty":1}],"v76-fms-informatics-02-digitale-werkzeuge-und-verantwortung":[{"type":"mc","prompt":"Eine Lernende lässt sich von einem KI-Chatbot eine Dosierungsempfehlung für ein Medikament geben. Wie handelt sie verantwortungsvoll?","options":["Sie übernimmt die Angabe, wenn die Antwort sehr sicher klingt.","Sie prüft die Angabe mit einer verlässlichen Fachquelle und fragt die Fachperson.","Sie fragt denselben Chatbot ein zweites Mal und nimmt die häufigere Antwort.","Sie gibt den Namen der Patientin ein, damit die Antwort genauer wird."],"answer":1,"explanation":"KI-Tools können überzeugend klingende Fehler liefern; medizinische Angaben werden mit verlässlichen Quellen geprüft, vertrauliche Daten gibt man nie ein.","difficulty":1}],"v76-fms-field-fms-health-03-ethik-und-kommunikation-im-gesundheitsfeld":[{"type":"mc","prompt":"Eine Angehörige ist nach einer schlechten Nachricht wütend und wirft der Pflegefachperson Versagen vor. Welche Reaktion entspricht einer guten Gesprächsführung?","options":["Das Gespräch abbrechen, bis die Angehörige sich beruhigt hat.","Die Wut ruhig zulassen, das Gefühl empathisch ansprechen und weiter zuhören.","Sofort erklären, dass die Pflegefachperson keine Schuld trägt.","Mit vielen medizinischen Details beweisen, dass alles richtig gemacht wurde."],"answer":1,"explanation":"Wut richtet sich oft gegen die Situation, nicht gegen die Person; wer sie zulässt und empathisch anspricht, statt sich zu rechtfertigen, entschärft das Gespräch.","difficulty":2}],"v76-fms-field-fms-social-work-01-soziologie-und-gesellschaft":[{"type":"mc","prompt":"Welche Entwicklung gilt als ein Grund dafür, dass Familienformen in der Schweiz vielfältiger geworden sind?","options":["Die sinkende Lebenserwartung","Die stärkere Individualisierung der Lebenswege","Die kürzere Ausbildungszeit junger Menschen","Die geringere Erwerbstätigkeit von Frauen"],"answer":1,"explanation":"Lebenswege werden heute weniger von Tradition vorgegeben und stärker selbst gewählt; die anderen Optionen beschreiben das Gegenteil der tatsächlichen Entwicklung.","difficulty":1}],"v76-fms-field-fms-social-work-02-psychologie-und-entwicklung":[{"type":"mc","prompt":"Jonas (12) erlebt die Trennung seiner Eltern, ist aber im Fussballklub gut eingebunden und hat einen Trainer, der ihn unterstützt. Was ist dieser Trainer im Sinne der Resilienzforschung?","options":["Ein Risikofaktor in der Person","Ein Schutzfaktor in der Umwelt","Eine problemorientierte Bewältigung","Ein Stressor nach Lazarus"],"answer":1,"explanation":"Eine stabile, zugewandte Bezugsperson ausserhalb der Familie gilt als wichtiger Schutzfaktor in der Umwelt, der Resilienz fördert.","difficulty":2}],"v76-fms-field-fms-social-work-03-soziale-institutionen-und-fallreflexion":[{"type":"mc","prompt":"Eine Sozialarbeiterin unterstützt eine Familie und muss zugleich prüfen, ob die Auflagen der Sozialhilfe eingehalten werden. Wie nennt man diese Spannung?","options":["Schweigepflicht","Doppelmandat von Hilfe und Kontrolle","Subsidiaritätsprinzip","Umlageverfahren"],"answer":1,"explanation":"Das Doppelmandat beschreibt, dass Soziale Arbeit den Klientinnen und Klienten hilft und zugleich im Auftrag der Gesellschaft kontrolliert; Subsidiarität regelt dagegen nur die Reihenfolge der Hilfen.","difficulty":2},{"type":"mc","prompt":"Welches Ziel für Frau A., die Schulden hat, erfüllt die SMART-Regel am besten?","options":["Frau A. zahlt ab morgen alle Schulden auf einmal zurück.","Frau A. soll ihre Finanzen besser im Griff haben.","Frau A. erstellt bis Ende März mit der Beraterin ein Monatsbudget und zahlt ab April monatlich 200 Franken Schulden ab.","Frau A. soll sich beim Geldausgeben mehr Mühe geben."],"answer":2,"explanation":"Nur dieses Ziel ist spezifisch, messbar (200 Franken pro Monat), realistisch und terminiert (Ende März, ab April); die anderen sind vage oder unrealistisch.","difficulty":2}],"v76-fms-field-fms-pedagogy-01-entwicklung-und-lernen":[{"type":"mc","prompt":"Ein Kind bekam beim Zahnarzt mehrmals eine schmerzhafte Spritze. Jetzt beginnt es schon beim Geruch der Praxis zu weinen. Welche Lernform erklärt das?","options":["Klassische Konditionierung","Operante Konditionierung durch Belohnung","Lernen durch Einsicht","Lernen am Modell"],"answer":0,"explanation":"Ein zuvor neutraler Reiz (der Geruch) wurde mit einem natürlichen Angstreiz (dem Schmerz) verknüpft und löst nun selbst die Reaktion aus; das ist klassische Konditionierung nach Pawlow.","difficulty":2}],"v76-fms-field-fms-pedagogy-03-beobachtung-kommunikation-und-reflexion":[{"type":"tf","prompt":"«Wie hast du die Pause heute erlebt?» ist eine offene Frage, die ein Kind zum Erzählen einlädt.","options":["Richtig","Falsch"],"answer":0,"explanation":"Offene Fragen lassen sich nicht mit Ja oder Nein beantworten und laden zum Erzählen ein; «War die Pause schön?» wäre dagegen eine geschlossene Frage.","difficulty":1}],"v76-fms-field-fms-communication-01-medienanalyse":[{"type":"mc","prompt":"Eine Zeitung deckt auf, dass eine Gemeinde Aufträge ohne Ausschreibung an Verwandte des Gemeindepräsidenten vergeben hat. Welche Funktion der Medien erfüllt sie damit vor allem?","options":["Werbung","Unterhaltung","Kritik und Kontrolle","Integration"],"answer":2,"explanation":"Medien decken Missstände auf und kontrollieren Politik und Wirtschaft; deshalb nennt man sie auch die vierte Gewalt. Unterhaltung oder Integration stehen hier nicht im Vordergrund.","difficulty":2}],"v76-fms-field-fms-communication-02-recherche-und-quellen":[{"type":"mc","prompt":"Welche der folgenden Quellen zur Handystrahlung ist eine Primärquelle?","options":["Ein Zeitungsartikel, der die Studie zusammenfasst","Der Originaltext einer wissenschaftlichen Studie","Ein Lexikonartikel über Mobilfunk","Ein Lehrbuchkapitel über Strahlung"],"answer":1,"explanation":"Die Studie selbst ist ein Dokument aus erster Hand; Zeitungsartikel, Lexikon und Lehrbuch berichten darüber und sind deshalb Sekundärquellen.","difficulty":2},{"type":"mc","prompt":"Du bereitest ein Interview mit einer Datenschutzbeauftragten vor. Was gehört in deinen Leitfaden?","options":["Fertige Zitate, die sie bestätigen soll","Nur Fragen, die mit Ja oder Nein beantwortet werden","Keine Fragen, damit das Gespräch spontan bleibt","Offene Fragen wie «Welche Erfahrungen haben Sie mit …?»"],"answer":3,"explanation":"Ein Leitfaden mit offenen Fragen gibt dem Gespräch Struktur und lädt zu ausführlichen Antworten ein; reine Ja-Nein-Fragen oder vorgegebene Zitate liefern keine echten Informationen.","difficulty":2}],"v76-fms-field-fms-design-01-wahrnehmung-und-analyse":[{"type":"mc","prompt":"Alle Schaltflächen einer Website haben dieselbe Farbe, sodass man sie als zusammengehörig erkennt. Welches Gestaltgesetz wirkt hier?","options":["Gesetz der Nähe","Gesetz der Kontinuität","Gesetz der Geschlossenheit","Gesetz der Ähnlichkeit"],"answer":3,"explanation":"Elemente mit gleicher Farbe, Form oder Grösse werden nach dem Gesetz der Ähnlichkeit als zusammengehörig gesehen; das Gesetz der Nähe würde über Abstände wirken.","difficulty":2},{"type":"mc","prompt":"In welcher Reihenfolge geht man bei einer Werkanalyse vor?","options":["Bewerten, deuten, beschreiben","Analysieren, deuten, beschreiben","Deuten, beschreiben, analysieren","Beschreiben, analysieren, deuten"],"answer":3,"explanation":"Zuerst wird sachlich beschrieben, dann untersucht, wie das Werk gemacht ist, und erst zuletzt eine Deutung formuliert, die sich auf Beschreibung und Analyse stützt.","difficulty":1}],"v76-fms-field-fms-design-02-gestaltungsprozess":[{"type":"mc","prompt":"Für eine lange gedruckte Broschüre mit viel Fliesstext suchst du eine gut lesbare Schrift. Welche Wahl entspricht der Lektion?","options":["Möglichst viele verschiedene Schriftfamilien","Eine Schrift mit Serifen wie Times","Eine sehr schmale Zierschrift in Grossbuchstaben","Hellgraue Schrift auf weissem Grund"],"answer":1,"explanation":"Serifenschriften sind in langen gedruckten Texten gut lesbar; viele Schriftfamilien wirken unruhig, Zierschriften und schwacher Kontrast erschweren das Lesen.","difficulty":2}],"v76-fms-field-fms-design-03-portfolio-und-prasentation":[{"type":"mc","prompt":"An deiner Portfoliopräsentation sagt eine Dozentin, eine Arbeit wirke unklar. Wie reagierst du professionell?","options":["Betonen, dass andere die Arbeit gut fanden","Die Arbeit kommentarlos überspringen","Sofort erklären, warum die Kritik falsch ist","Zuhören, nachfragen, was genau unklar wirkt, und dich bedanken"],"answer":3,"explanation":"Kritik ist in der Gestaltung wertvoll: Wer zuhört, gezielt nachfragt und sich bedankt, erhält brauchbare Hinweise; wer sich sofort verteidigt, blockiert das Gespräch.","difficulty":2}],"v76-fms-field-fms-music-theatre-01-analyse-und-interpretation":[{"type":"mc","prompt":"Welcher Teil folgt in der Pyramide nach Freytag direkt auf den Höhepunkt und Wendepunkt?","options":["Katastrophe oder Lösung","Exposition","Steigende Handlung mit erregendem Moment","Fallende Handlung mit retardierendem Moment"],"answer":3,"explanation":"Nach Freytag folgen Exposition, steigende Handlung, Höhepunkt mit Wendepunkt, fallende Handlung mit retardierendem Moment und zuletzt Katastrophe oder Lösung.","difficulty":2}],"v76-fms-field-fms-music-theatre-02-auffuhrung-und-produktion":[{"type":"mc","prompt":"In welcher Probenart werden grössere Teile oder das ganze Stück ohne Unterbrechung gespielt, damit Übergänge und Spannungsbogen entstehen?","options":["Kennenlernprobe","Leseprobe","Technische Probe","Durchlaufprobe"],"answer":3,"explanation":"In Durchlaufproben wird ohne Unterbrechung gespielt; die Leseprobe klärt Text und Rollen, die technische Probe stimmt Licht, Ton und Umbauten ab.","difficulty":2}]};
var n=0,fehlt=[];Object.keys(Z).forEach(function(cid){var c=(M.chapters||[]).filter(function(x){return x.id===cid;})[0];if(!c){fehlt.push(cid);return;}c.questions=c.questions||[];Z[cid].forEach(function(src,k){var q=JSON.parse(JSON.stringify(src));q.id=cid+"-r154-"+(k+1);q.chapterId=cid;q.contentRevision="r154-outcome";if(c.questions.some(function(x){return x&&x.id===q.id;}))return;c.questions.push(q);(M.QUESTION_REGISTRY_V1217||{})[q.id]=JSON.parse(JSON.stringify(q));n++;});});
M.__r154Bericht={gesetzt:n,fehlt:fehlt};})();